// The page inside the dash's frame (../ecuai/docs/plan-dashes.md, "How a dash runs"). The frame is sandboxed
// (allow-scripts only: an opaque origin, no storage, no parent, no forms, no popups) and its own CSP
// allows no network at all, so a dash can only draw, take touches and talk to the app over the one
// MessageChannel the app hands it. Neither the sandbox nor CSP covers WebRTC, so the runner takes it
// away before any dash code runs. It receives the dash's modules as text, makes each a blob: URL (its
// imports already rewritten by the loader to 'tl-mod:<n>' tokens at the places the loader lists,
// dependencies first), imports the entry and calls its default export with `api`.
//
// The runner's source goes into the srcdoc as an inline script, allowed by its hash: the app's CSP
// (index.html, inherited by the srcdoc) lists that hash and blob:, and tests/unit/dash-runtime.test.js
// checks it. Edit runner() and the hash changes: run the test, it prints the new one.

function runner() {
  // A peer connection's STUN and DNS lookups go anywhere, whatever CSP says: every way to make one
  // is deleted, then pinned to undefined so the dash can't put it back. A frame made inside this one
  // gets an opaque origin of its own (the sandbox), so it can't hand back a fresh copy.
  const gone = (o, k) => { try { delete o[k]; Object.defineProperty(o, k, { value: undefined, writable: false, configurable: false }); } catch { /* already fixed */ } };
  for (const k of Object.getOwnPropertyNames(globalThis)) if (/^(webkit|moz)?(RTC|MediaStream)/.test(k)) gone(globalThis, k);
  for (const k of ['mediaDevices', 'getUserMedia', 'webkitGetUserMedia']) gone(Navigator.prototype, k);

  let port = null, root = null, store = {}, seq = 0, first = true, api = null;
  const nav = { shown: true, show() { send({ type: 'nav', show: true }); }, hide() { send({ type: 'nav', show: false }); } };
  const on = {}, waiting = new Map(), lag = { n: 0, sum: 0, max: 0 }, posted = [];
  const send = (m) => { try { port.postMessage(m); } catch { /* app gone */ } };
  const fire = (ev, ...a) => { for (const fn of on[ev] || []) { try { fn(...a); } catch (e) { fail(e); } } };
  const text = (e) => String(e?.stack || e?.message || e).slice(0, 300);
  const fail = (e) => send({ type: 'error', message: text(e) });
  addEventListener('error', (e) => fail(e.error || e.message));
  addEventListener('unhandledrejection', (e) => fail(e.reason));

  // Paint lag: from the app posting a reading (absolute ms) to the next frame painting it. The first
  // one painted is told to the app (its load metric).
  const painted = () => {
    if (first) { first = false; send({ type: 'painted' }); }
    const now = performance.timeOrigin + performance.now();
    for (const t of posted.splice(0)) { const d = now - t; lag.n++; lag.sum += d; lag.max = Math.max(lag.max, d); }
  };

  function start(m) {
    const css = document.createElement('style');
    css.textContent = m.css || '';
    document.head.append(css);
    document.body.innerHTML = '<div class="dash" id="root"></div>';
    root = document.getElementById('root');
    store = m.store || {};
    nav.shown = m.nav !== false;
    const urls = [];
    for (const mod of m.modules) {
      let code = mod.code;
      for (const [at, n] of [...(mod.imports || [])].reverse()) {
        const token = `tl-mod:${n}`;
        if (code.startsWith(token, at) && urls[n]) code = code.slice(0, at) + urls[n] + code.slice(at + token.length);
      }
      urls.push(URL.createObjectURL(new Blob([code], { type: 'text/javascript' })));
    }
    api = {
      root, units: m.units || {}, tune: m.tune || null,
      history: m.history || null, bridge: m.bridge || '', params: m.params || null, nav,
      // A 'settings' handler puts the app's gear over the dash (with the tab bar); a tap on it fires it.
      on(ev, fn) { if (ev === 'settings' && !on.settings) send({ type: 'gear' }); (on[ev] ||= []).push(fn); },
      setUnit(kind, key) { send({ type: 'unit', kind, key }); },
      request(what, args) {
        return new Promise((resolve, reject) => { const id = ++seq; waiting.set(id, { resolve, reject }); send({ type: 'request', id, what, args }); });
      },
      store: {
        get: (k) => store[k],
        set(k, v) { store[k] = v; send({ type: 'request', id: 0, what: 'store', args: { k, v } }); },
      },
    };
    import(urls[urls.length - 1]).then((g) => {
      const mount = typeof g.default === 'function' ? g.default : g.default?.mount;
      if (typeof mount !== 'function') throw new Error('the entry module has no default export function');
      return mount(api);
    }).then(() => send({ type: 'ready' }), (e) => send({ type: 'failed', message: text(e) }));
    // The frame rate, beside the paint lag: a phone may hold a frame to 30 fps until it is touched.
    let frames = 0, since = performance.now();
    (function count() { frames++; requestAnimationFrame(count); })();
    setInterval(() => {
      const now = performance.now(), fps = Math.round((frames * 1000) / Math.max(1, now - since));
      send({ type: 'hb', lag: lag.n ? Math.round(lag.sum / lag.n) : null, lagMax: Math.round(lag.max), n: lag.n, fps });
      lag.n = 0; lag.sum = 0; lag.max = 0; frames = 0; since = now;
    }, 1000);
  }

  function onMessage(e) {
    const m = e.data || {};
    if (m.type === 'init') return start(m);
    // The app's dash fonts, when they have loaded (they don't hold the start up): a dash that draws
    // text on canvas redraws on 'fonts'.
    if (m.type === 'fonts') {
      for (const f of m.fonts || []) { try { document.fonts.add(new FontFace(f.family, f.data, f.desc)); } catch { /* bad font: the fallback shows */ } }
      return document.fonts.ready.then(() => fire('fonts'));
    }
    if (m.type === 'r') {
      posted.push(m.at);
      if (posted.length === 1) requestAnimationFrame(painted);
      return fire('reading', m.v, m.t, m);
    }
    if (m.type === 'units') return fire('units', m.units);
    if (m.type === 'nav') { nav.shown = !!m.shown; return fire('nav', nav.shown); }
    if (m.type === 'outside') return fire('outside');
    if (m.type === 'settings') return fire('settings');
    if (m.type === 'tune' && api) { api.tune = m.tune || null; return fire('tune', api.tune); }
    if (m.type === 'rows') return fire('rows', m);
    if (m.type === 'trend') return fire('trend', m.rows);
    if (m.type === 'reply') {
      const w = waiting.get(m.id);
      if (!w) return;
      waiting.delete(m.id);
      if (m.error) w.reject(new Error(m.error)); else w.resolve(m.result);
    }
  }

  addEventListener('message', (e) => {
    if (port || e.source !== parent || !e.ports?.[0]) return;
    port = e.ports[0];
    port.onmessage = onMessage;
  });
}

export const RUNNER_JS = `(${runner})();`;

// The frame's own policy: nothing from the network, scripts only from the dash's blob: modules and
// the runner itself. The app's policy applies too (the srcdoc inherits it).
export const frameCsp = (hash) => [
  "default-src 'none'", `script-src blob: '${hash}'`, "style-src 'unsafe-inline'", 'img-src data: blob:',
  'font-src data:', "connect-src 'none'", "worker-src 'none'", "frame-src 'none'", "form-action 'none'", "base-uri 'none'",
].join('; ');

// SHA-256 of the runner as CSP wants it ('sha256-<base64>'); works in the browser and in node.
export async function runnerHash() {
  const bytes = new Uint8Array(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(RUNNER_JS)));
  return `sha256-${btoa(String.fromCharCode(...bytes))}`;
}

export async function srcdoc() {
  const csp = frameCsp(await runnerHash());
  return `<!doctype html><html><head><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="${csp}">`
    + '<style>html,body{margin:0;height:100%;overflow:hidden;background:transparent}#root{position:absolute;inset:0}</style>'
    + `</head><body><script>${RUNNER_JS}</script></body></html>`;
}

// A dash package's manifest (dash.json), checked before a dash runs (../ecuai/docs/plan-dashes.md, "The manifest"). Everything here is untrusted text
// from a package: checked for type and size, unknown keys dropped. Pure: also run by the unit tests.

const ID = /^[a-z0-9][a-z0-9-]{1,39}$/;
const PATH = /^(?!\/)(?!.*\.\.)[\w./-]{1,120}\.js$/;
const CSS = /^(?!\/)(?!.*\.\.)[\w./-]{1,120}\.css$/;
const VERSION = /^\d{1,4}\.\d{1,4}\.\d{1,6}$/;
const FEEDS = ['history', 'rows', 'trend', 'tune'];
// The dash API this app speaks (the bridge, api, the reading and feed shapes; dash-kit/README.md). A
// package names the version it was written for; one asking for a newer one than this app has is
// refused rather than started half-working. Raised only for a change an old dash would break on.
export const API = 1;

const str = (v, max) => (typeof v === 'string' && v.length <= max ? v : null);

// { ok, errors: [text], manifest } with defaults filled in.
export function checkManifest(raw) {
  const errors = [], m = raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {};
  const need = (name, v, why) => { if (v === null || v === undefined) errors.push(`${name}: ${why}`); return v; };
  const out = {
    id: need('id', ID.test(m.id ?? '') ? m.id : null, 'lowercase letters, digits and dashes, 2 to 40'),
    name: need('name', str(m.name, 40) || null, 'text up to 40 characters'),
    version: need('version', VERSION.test(m.version ?? '') ? m.version : null, 'major.minor.build'),
    api: need('api', Number.isInteger(m.api) && m.api >= 1 && m.api <= 999 ? m.api : null, `the dash API it was written for, a whole number (this app: ${API})`),
    author: str(m.author, 60) ?? '',
    license: str(m.license, 30) ?? '',
    description: str(m.description, 200) ?? '',
    entry: need('entry', PATH.test(m.entry ?? 'index.js') ? (m.entry ?? 'index.js') : null, 'a .js path inside the package'),
    styles: [],
    basedOn: null,
    feeds: [],
  };
  if (out.api > API) errors.push(`api: needs a newer app (this dash is for dash API ${out.api}, this app has ${API}): update the app`);
  const styles = m.styles ?? [];
  if (!Array.isArray(styles) || styles.length > 8 || !styles.every((p) => CSS.test(p))) errors.push('styles: up to 8 .css paths inside the package');
  else out.styles = [...styles];
  // A fork names the dash it came from, so it shows how far behind that dash it is.
  if (m.basedOn != null) {
    if (ID.test(m.basedOn?.id ?? '') && VERSION.test(m.basedOn?.version ?? '')) out.basedOn = { id: m.basedOn.id, version: m.basedOn.version };
    else errors.push('basedOn: { id, version } of the dash it was copied from');
  }
  const feeds = m.feeds ?? [];
  if (!Array.isArray(feeds) || !feeds.every((f) => FEEDS.includes(f))) errors.push(`feeds: any of ${FEEDS.join(', ')}`);
  else out.feeds = [...new Set(feeds)];
  return { ok: !errors.length, errors, manifest: out };
}

// The import specifiers in a module's text, for the dash loader (loader.js): static imports,
// re-exports (`export ... from`) and import() of a string literal, with where each specifier's text
// sits so the loader can rewrite exactly it. A small lexer, one pass, so no input can make it slow
// (a regular expression here once took 42 s on 360 KB of crafted text): it skips comments, strings,
// template literals (their ${} parts are code) and regular expressions, so an import written inside
// any of those is not one. Pure: also run by the unit tests.

const REGEX_AFTER = new Set(['return', 'typeof', 'instanceof', 'in', 'of', 'new', 'delete', 'void', 'throw', 'case', 'do', 'else', 'yield', 'await']);
const isWord = (c) => (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c === '_' || c === '$' || c > '\x7f';
const isSpace = (c) => c === ' ' || c === '\t' || c === '\n' || c === '\r' || c === '\f' || c === '\v' || c === ' ' || c === '﻿';

// [{ spec, at, end }]: code.slice(at, end) === spec, the text between the quotes.
export function scanImports(code) {
  const out = [], braces = [], n = code.length;
  let i = 0, prev = null;   // prev: the last token ('word:<w>', 'str', 'num' or the punctuation itself)
  let st = null;            // an import or export being read: { k: 'import'|'export'|'dyn', n: tokens since, from }

  // Past a quoted string starting at i; stops at a line end if it isn't closed.
  const skipString = (q) => { let j = i + 1; while (j < n && code[j] !== q && code[j] !== '\n') j += code[j] === '\\' ? 2 : 1; return Math.min(j, n); };
  // A template from i (just past a ` or a ${...}'s closing brace) to its end or its next ${.
  function template() {
    while (i < n) {
      const c = code[i];
      if (c === '\\') { i += 2; continue; }
      if (c === '`') { i++; return; }
      if (c === '$' && code[i + 1] === '{') { i += 2; braces.push('${'); return; }
      i++;
    }
  }
  const regexAllowed = () => prev === null || (prev.startsWith('word:') ? REGEX_AFTER.has(prev.slice(5)) : !['str', 'num', ')', ']', '}'].includes(prev));

  while (i < n) {
    const c = code[i];
    if (isSpace(c)) { i++; continue; }
    if (c === '/' && code[i + 1] === '/') { while (i < n && code[i] !== '\n') i++; continue; }
    if (c === '/' && code[i + 1] === '*') { const e = code.indexOf('*/', i + 2); i = e < 0 ? n : e + 2; continue; }
    if (c === '"' || c === "'") {
      const e = skipString(c);
      if (st && (st.k === 'dyn' || (st.k === 'import' && st.n === 0) || st.from)) out.push({ spec: code.slice(i + 1, e), at: i + 1, end: e });
      st = null; prev = 'str'; i = e + 1; continue;
    }
    if (c === '`') { i++; template(); st = null; prev = 'str'; continue; }
    if (c === '/' && regexAllowed()) {
      let j = i + 1, cls = false;
      while (j < n && code[j] !== '\n' && (cls || code[j] !== '/')) { if (code[j] === '\\') j++; else if (code[j] === '[') cls = true; else if (code[j] === ']') cls = false; j++; }
      i = j + 1; while (i < n && isWord(code[i])) i++;   // its flags
      st = null; prev = 'str'; continue;
    }
    if (isWord(c)) {
      let j = i + 1;
      while (j < n && isWord(code[j])) j++;
      const w = code.slice(i, j), afterDot = prev === '.';
      if (c >= '0' && c <= '9') { st = null; prev = 'num'; i = j; continue; }
      if ((w === 'import' || w === 'export') && !afterDot) st = { k: w, n: 0, from: false };
      else if (st && st.k !== 'dyn') { st.from = w === 'from' && st.n > 0; st.n++; }
      else st = null;
      prev = `word:${w}`; i = j; continue;
    }
    // Punctuation: an import clause takes { } * , and import( starts a dynamic import.
    if (c === '{') braces.push('{');
    if (c === '}') { if (braces.pop() === '${') { i++; template(); st = null; prev = 'str'; continue; } }
    if (st && c === '(' && st.k === 'import' && st.n === 0) st = { k: 'dyn' };
    else if (st && st.k !== 'dyn' && (c === '{' || c === '}' || c === '*' || c === ',')) { st.from = false; st.n++; }
    else st = null;
    prev = c; i++;
  }
  return out;
}

// Loads a dash package for the frame (../ecuai/docs/plan-dashes.md, "How a dash runs"): its manifest
// and every module the entry imports, in dependency order with the entry last, each import rewritten
// to a 'tl-mod:<n>' token the runner (runner.js) swaps for the blob: URL of module n, at the places
// listed with the module (so the same text anywhere else in a dash is left alone).
// Modules import each other by relative path, and how far a path may reach depends on the package:
//   - the app's own dash (DEFAULT_DASH, dashes/<id>/: it ships and is tested with the app) may import
//     its own folder, the kit (kit/) and the vendored uPlot, and gets the kit's styles;
//   - an installed package (a set of texts, library.js) only its own files: the app's modules change
//     under it with every release, so it must carry everything it uses (scripts/fork_dash.mjs makes a
//     self-contained copy).
// Every dash gets the app's dash fonts. The graph code here is pure (no DOM): the fork tool and the
// unit tests run it in node.
import { checkManifest } from 'tl-mod:1';
import { scanImports } from 'tl-mod:2';

// What the app's own dash may import besides its own folder (paths under src/).
export const SHARED = ['kit/', 'packages/uplot/'];
// The kit's styles, in the order the app's own dash gets them (before its own): the themes (their @font-face
// rules taken out: a frame can't fetch, the fonts go as bytes), uPlot's, the boxes'.
export const KIT_STYLES = ['kit/themes.css', 'packages/uplot/uPlot.min.css', 'kit/boxes.css'];
// What a package may hold: files (an installed package's, library.js; the modules one entry reaches) and their text in all.
export const LIMITS = { files: 64, bytes: 1_500_000 };

export const importsOf = (code) => scanImports(code).map((m) => m.spec);
export const withoutFontFaces = (css) => css.replace(/@font-face\s*\{[^}]*\}/g, '');

// Module ids: an app file as 'app:<path under src/>', a package's file as 'pkg:<path>'.
function join(dir, rel) {
  const parts = dir ? dir.split('/') : [];
  for (const p of rel.split('/')) {
    if (p === '.' || p === '') continue;
    if (p === '..') { if (!parts.length) return null; parts.pop(); } else parts.push(p);
  }
  return parts.join('/');
}
// The id a relative import leads to, or null (a bare name, a URL, or a path out of the top).
export function resolve(fromId, spec) {
  if (!spec.startsWith('./') && !spec.startsWith('../')) return null;
  const [scheme, path] = [fromId.slice(0, 4), fromId.slice(4)];
  const p = join(path.split('/').slice(0, -1).join('/'), spec);
  return p === null ? null : scheme + p;
}
// Where the app's own dash's modules may come from.
export const builtinMay = (id) => (mid) => mid.startsWith(`app:dashes/${id}/`) || SHARED.some((root) => mid.startsWith(`app:${root}`));

// Every module the entry imports, read through read(id) (a promise of the text, or null):
// { order: ids with dependencies first and the entry last, texts: id -> text, found: id -> its imports
// (scanImports), deps: id -> {spec: id} }. may(id): whether a module may be part of the package
// (default: any id a relative path reaches).
export async function moduleGraph(entryId, read, { may = () => true } = {}) {
  const texts = new Map(), deps = new Map(), found = new Map();
  let bytes = 0;
  async function visit(id) {
    if (texts.has(id)) return;
    if (texts.size >= LIMITS.files) throw new Error(`more than ${LIMITS.files} modules`);
    texts.set(id, null);
    const code = await read(id);
    if (typeof code !== 'string') throw new Error(`${id}: not found`);
    bytes += code.length;
    if (bytes > LIMITS.bytes) throw new Error('package too big');
    texts.set(id, code);
    const ds = {}, specs = scanImports(code);
    found.set(id, specs);
    for (const { spec } of specs) {
      const to = resolve(id, spec);
      if (!to || !may(to)) throw new Error(`${id.slice(4)}: can't import '${spec}': ${OUTSIDE}`);
      ds[spec] = to;
    }
    deps.set(id, ds);
    await Promise.all(Object.values(ds).map(visit));   // side by side: one round trip per level of imports, not per module
  }
  await visit(entryId);
  const order = [], state = new Map();
  (function walk(id) {
    if (state.get(id) === 'done') return;
    if (state.get(id) === 'open') throw new Error(`import cycle at ${id}`);
    state.set(id, 'open');
    for (const to of Object.values(deps.get(id))) walk(to);
    state.set(id, 'done');
    order.push(id);
  })(entryId);
  return { order, texts, found, deps };
}
const OUTSIDE = 'a dash imports only its own files, by relative path, and must carry everything it uses'
  + ' (hub/scripts/fork_dash.mjs makes a self-contained copy of a dash, kit included)';

// The module list for the runner: [{id, code, imports}], dependencies first, the entry last; imports:
// [[at, n]], each token 'tl-mod:<n>' at offset `at` of code.
export async function buildModules(entryId, read, opts) {
  const { order, texts, found, deps } = await moduleGraph(entryId, read, opts);
  const index = new Map(order.map((id, n) => [id, n]));
  return order.map((id) => {
    const text = texts.get(id), imports = [];
    let code = '', from = 0;
    for (const { spec, at, end } of found.get(id)) {
      const n = index.get(deps.get(id)[spec]);
      code += text.slice(from, at);
      imports.push([code.length, n]);
      code += `tl-mod:${n}`;
      from = end;
    }
    return { id, code: code + text.slice(from), imports };
  });
}

// ---------------------------------------------------------------- in the app

const appBase = () => new URL('../../', import.meta.url);   // src/
const fetchApp = (path, as) => fetch(new URL(path, appBase())).then((r) => (r.ok ? r[as]() : null), () => null);
// The app's own files by their path under src/ (text, or bytes for a font; null: not there): fetched
// from beside this module. A page with no server (the dash preview, lab/preview.js) hands them over.
let appFiles = { text: (path) => fetchApp(path, 'text'), bytes: (path) => fetchApp(path, 'arrayBuffer') };
export function setAppFiles(files) { appFiles = files; }
// make(arg)'s promise, kept by key once it has worked: one that rejects, or whose value good() refuses,
// is dropped, so the next call asks again (a phone coming back online).
function remember(make, good = () => true) {
  const kept = new Map();
  return (key, arg = key) => {
    if (!kept.has(key)) {
      const p = make(arg);
      kept.set(key, p);
      p.then(good, () => false).then((ok) => { if (!ok && kept.get(key) === p) kept.delete(key); });
    }
    return kept.get(key);
  };
}
// The built-in dash's text files as one file, { files: { path: text } }, written at deploy
// (scripts/dash_bundle.mjs, by scripts/release.py): one request instead of about fifty. A checkout has
// none (null): the files are then read one by one, which is also what any file the bundle lacks falls
// back to.
export const BUNDLE = 'dashes/bundle.json';
let bundle = null;
const bundled = () => (bundle ??= Promise.resolve(appFiles.text(BUNDLE)).then((t) => { const b = JSON.parse(t); return b && typeof b.files === 'object' ? b.files : null; }).catch(() => null));
// An app file's text (a path under src/), or null.
const readApp = (path) => appText(path);
const appText = remember((path) => bundled().then((files) => (typeof files?.[path] === 'string' ? files[path] : appFiles.text(path))), (t) => t !== null);

// The one dash shipped in the app's own files (dashes/<id>/): the default, and what safe start and a
// dash that fails fall back to, so it can't be removed, replaced or lost with the phone's storage.
// Every other dash is a package from GitHub or a folder (library.js), all treated alike.
export const DEFAULT_DASH = 'tunerloop-dash';

// { manifest, modules, css, builtin } for the app's own dash (its id), or a package { files: {path: text} }
// (library.js). css: the package's own styles (manifest styles); the app's own dash also gets kitCss().
export const loadPackage = (ref) => packageOf(typeof ref === 'string' ? `builtin:${ref}` : `user:${ref.hash}`, ref);
const packageOf = remember(async (ref) => {
  const builtin = typeof ref === 'string';
  // A file of the package, by its path in it: a built-in's is the app's, an installed one's its own text.
  const id = (p) => (builtin ? `app:dashes/${ref}/${p}` : `pkg:${p}`);
  const read = (mid) => (mid.startsWith('app:') ? readApp(mid.slice(4)) : Promise.resolve(ref.files?.[mid.slice(4)] ?? null));
  const manifest = await manifestOf(read(id('dash.json')));
  const css = (await Promise.all(manifest.styles.map((p) => read(id(p))))).map((t, k) => {
    if (typeof t !== 'string') throw new Error(`${manifest.styles[k]}: not found`);
    return t;
  }).join('\n');
  return { manifest, modules: await buildModules(id(manifest.entry), read, builtin ? { may: builtinMay(ref) } : {}), css, builtin };
});

// A dash.json's text (or a promise of it; null: missing) as its checked manifest, or throws.
async function manifestOf(text) {
  const raw = await text;
  if (typeof raw !== 'string') throw new Error('dash.json: not found');
  let json;
  try { json = JSON.parse(raw); } catch { throw new Error('dash.json is not JSON'); }
  const { ok, errors, manifest } = checkManifest(json);
  if (!ok) throw new Error(`dash.json: ${errors.join('; ')}`);
  return manifest;
}
// Read once and kept, unless a read failed (offline before the files were saved): then what did load
// is used this time (a missing font leaves the fallback) and the next start asks again.
function once(make) {
  const get = remember(make, (r) => r.complete);
  return () => get('').then((r) => r.value);
}

// The kit's styles, for the app's own dash's frame only.
export const kitCss = once(async () => {
  const texts = await Promise.all(KIT_STYLES.map(readApp));
  return { value: withoutFontFaces(texts.map((t) => t || '').join('\n')), complete: texts.every((t) => t !== null) };
});

// The dash fonts, for every frame: part of the host API (dash kit README, "Fonts"), since a package
// can't carry binary files yet. Each @font-face in kit/themes.css as its file's bytes with its
// descriptors; the runner adds them with FontFace.
export const dashFonts = once(async () => {
  const themes = await readApp('kit/themes.css');
  const faces = [...(themes || '').matchAll(/@font-face\s*\{([^}]*)\}/g)].map((m) => m[1]);
  const fonts = (await Promise.all(faces.map(async (f) => {
    const get = (k) => f.match(new RegExp(`${k}\\s*:\\s*([^;]+);`))?.[1].trim();
    const path = resolve('app:kit/themes.css', get('src')?.match(/url\("?([^")]+)"?\)/)?.[1] || '');
    if (!path) return null;
    const data = await appFiles.bytes(path.slice(4));
    const desc = Object.fromEntries([['weight', get('font-weight')], ['stretch', get('font-stretch')], ['style', get('font-style')]].filter(([, v]) => v));
    return data && { family: get('font-family').replace(/"/g, ''), data, desc };
  }))).filter(Boolean);
  return { value: fonts, complete: themes !== null && fonts.length === faces.length };
});

// The limits on what a dash's frame may send the app (frame.js, ../ecuai/docs/plan-dashes.md
// "The bridge"): a frame is untrusted code that can post as fast as it likes, so every message
// costs it a token, its store values are sized before anything copies them, and its history
// requests (each one a hub call under the person's session) go one at a time, a few a minute, with
// repeats answered from a short cache. Pure: also run by the unit tests.

// A token bucket: `rate` tokens a second, holding at most `burst`. take(now) spends one, or says no.
export function tokenBucket(rate, burst) {
  let tokens = burst, at = null;
  return {
    take(now) {
      if (at !== null) tokens = Math.min(burst, tokens + ((now - at) / 1000) * rate);
      at = now;
      if (tokens < 1) return false;
      tokens -= 1;
      return true;
    },
  };
}

// About how long v is as JSON, or -1 for anything that isn't plain JSON data (a function, a Map, a
// Date, NaN, a cycle, too deep) or passes `budget` on the way: it stops there, so a huge value costs
// no more than the budget to refuse.
export function jsonSize(v, budget, depth = 0) {
  if (v === null || typeof v === 'boolean') return 5;
  if (typeof v === 'number') return Number.isFinite(v) ? String(v).length : -1;
  if (typeof v === 'string') return v.length + 2 <= budget ? v.length + 2 : -1;
  if (typeof v !== 'object' || depth >= 8) return -1;
  const array = Array.isArray(v), proto = Object.getPrototypeOf(v);
  if (!array && proto !== Object.prototype && proto !== null) return -1;
  let size = 2;
  for (const k of array ? v.keys() : Object.keys(v)) {
    size += (array ? 0 : String(k).length + 3) + 1;
    if (size > budget) return -1;
    const s = jsonSize(v[k], budget - size, depth + 1);
    if (s < 0) return -1;
    size += s;
  }
  return size <= budget ? size : -1;
}

// A dash's store as read back from the phone: a plain object within the limits, else empty (a store
// the app can't trust is dropped rather than handed to the dash).
export function cleanStore(v, max, maxKeys) {
  return v && typeof v === 'object' && !Array.isArray(v) && Object.keys(v).length <= maxKeys && jsonSize(v, max) >= 0 ? v : {};
}

// A heartbeat's paint-lag and frame-rate numbers, if they are sane (they go to the app's metrics), else nulls.
// fps: the frame's animation frames in the last second (a phone may hold a frame to 30 until touched).
export function checkBeat(m) {
  const num = (x, max) => (typeof x === 'number' && Number.isFinite(x) && x >= 0 && x <= max ? Math.round(x) : null);
  const n = Number.isInteger(m?.n) && m.n >= 0 && m.n <= 1000 ? m.n : 0, lag = num(m?.lag, 60_000), lagMax = num(m?.lagMax, 60_000);
  return { n: lag === null ? 0 : n, lag, lagMax: lagMax ?? 0, fps: num(m?.fps, 1000) };
}

// History requests: one at a time (the rest wait in a short queue), at most `perMin` a minute, and a
// request asked again within `cacheMs` gets the last answer without a hub call (one asked while the
// same is waiting or running shares its answer). run(key, fn) -> promise; fn() makes the call.
export function requestGate({ perMin, cacheMs, queue: maxQueue, clock = Date.now }) {
  const cache = new Map(), open = new Map(), waiting = [], calls = [];
  let busy = false;
  function next() {
    if (busy || !waiting.length) return;
    const w = waiting.shift();
    busy = true;
    Promise.resolve().then(w.fn).then((r) => { cache.set(w.key, { at: clock(), r }); w.resolve(r); }, w.reject)
      .finally(() => { open.delete(w.key); busy = false; next(); });
  }
  return {
    run(key, fn) {
      const now = clock();
      for (const [k, e] of cache) if (now - e.at >= cacheMs) cache.delete(k);
      if (cache.has(key)) return Promise.resolve(cache.get(key).r);
      if (open.has(key)) return open.get(key);
      while (calls.length && now - calls[0] >= 60_000) calls.shift();
      if (calls.length >= perMin) return Promise.reject(new Error('too many history requests: try again in a minute'));
      if (waiting.length >= maxQueue) return Promise.reject(new Error('too many history requests at once'));
      calls.push(now);
      const w = { key, fn };
      const promise = new Promise((resolve, reject) => { w.resolve = resolve; w.reject = reject; });
      open.set(key, promise);
      waiting.push(w);
      next();
      return promise;
    },
  };
}

// A dash's health as plain functions (no DOM), checked by tests/unit/dash-rules.test.js: the
// watchdog's timing and how often a built-in dash is started again after it fails.
//
// The watchdog counts how long a frame has been silent (no heartbeat), but only over time the app
// itself was running and the dash was on screen. On an iPhone (and in some Chromium setups) the frame
// shares the app's thread: when the page stalls (a slow phone, iOS pausing the page without telling
// it, a long garbage collection) the frame's heartbeat stalls with it, and when the page resumes the
// app's check can run before the heartbeat queued behind it. So a check that runs late means the
// stall was the app's: that time is forgiven, never counted against the dash.
export const WATCH = { silentMs: 5000, lateMs: 2000 };   // checks run every second; one 2 s late was a stall

// st: the last state ({at, quiet}) or null; now: ms; onScreen: the dash is showing (Car tab, page
// visible, not the status checklist). Returns the next state with `dead` true once the frame has
// been silent for silentMs of counted time. Off screen nothing is counted and the count starts again.
export function watchStep(st, now, onScreen, w = WATCH) {
  if (!onScreen || !st) return { at: now, quiet: 0, dead: false };
  const gap = Math.max(0, now - st.at);
  const quiet = st.quiet + (gap <= w.lateMs ? gap : 0);   // a late check: the app stalled, forgive it
  return { at: now, quiet, dead: quiet >= w.silentMs };
}
// A heartbeat came in at now: the silence starts again from there.
export const watchBeat = (st, now) => (st ? { at: now, quiet: 0, dead: false } : st);

// A built-in dash that fails (any reason: a stall the watchdog misread, a load that failed offline)
// is started again after these waits, then left stopped with the note. Only built-ins: an installed
// dash that fails stays stopped, so a misbehaving one can't loop. The count starts again once a
// restarted dash has run for okMs.
export const RETRY = { waits: [1000, 4000, 15000], okMs: 60_000 };
// The wait before restart number `tries` (0 for the first), or null: stop trying.
export const retryWait = (tries, builtin, r = RETRY) => (builtin && tries < r.waits.length ? r.waits[tries] : null);

// The Car tab's decisions on the app's side as plain functions (no DOM), checked by
// tests/unit/dash-rules.test.js: the status checklist, when the dash shows, dims or gives way to it,
// the live playback clock, and which chart rows a dash is sent.

// The car's name as people see it: the name someone gave it, else "Your car" (never the
// bridge's own name, which is for us).
export function carName(b) {
  const n = typeof b?.car_name === 'string' ? b.car_name.trim() : '';
  return n || 'Your car';
}

// The Bridge as people see it: "Bridge (914)" once the car has a name, else "Bridge".
export function bridgeName(b) {
  const n = typeof b?.car_name === 'string' ? b.car_name.trim() : '';
  return n ? `Bridge (${n})` : 'Bridge';
}

// The connection screen on the Car tab when no live numbers show, in two groups: this phone's
// Internet and its Local Wi-Fi to the Bridge, then the Bridge's Internet and its ECU. Each row is
// {id, group, text, state, note}: text is the link's name and never changes; note is its status,
// shown on a line below it, '' when it's ticked (ok). group 'phone' or 'bridge'; state ok; fail;
// half (the server is up but needs a sign-in); idle (not working, but normal: the ECU with the key
// off, Local Wi-Fi while the internet carries everything); wait (on its way); skip (can't be checked
// from this phone now).
//
// The links are independent, so every row says its own state (../ecuai/docs/plan-local-live.md,
// "The rules"): the gauges show through Direct (phone and Bridge on the same Wi-Fi, needs no
// internet once the phone is paired) or through the internet (both online, signed in).
//   server: hubState (rules.js); b: the bridge row (undefined: never connected, or not loaded);
//   online; seen: "9:41 pm" of its last beat; ecuOn: ecuAnswering (rules.js); live: liveState().row;
//   direct: {paired, open, tried, ecu} (direct.js directInfo; tried: the first try to reach the
//   box is over; ecu: the box's own state text); phoneOnline: navigator.onLine (false: this phone
//   has no network at all; true with the server unreached: the server isn't answering).
export function statusRows({ server, b, online, seen, ecuOn, live, direct = {}, phoneOnline = false }) {
  const hubOk = server === 'ok';
  const OK = { state: 'ok', note: '' };
  const PHONE = {
    ok: OK,
    checking: { state: 'wait', note: 'Searching…' },
    offline: { state: 'fail', note: phoneOnline ? 'Server not answering' : 'No connection' },
    signin: { state: 'half', note: 'Sign in needed' },
  };
  const net = !hubOk ? { state: 'skip', note: 'Can\'t check' }
    : !b ? { state: 'fail', note: 'Never connected' }
      : online ? OK
        : { state: 'fail', note: `No connection${seen ? `, last seen ${seen}` : ''}` };
  // Local Wi-Fi: while the internet path is there, not finding the Bridge on the Wi-Fi is normal
  // (the phone is away from the car).
  // After the first try, away from the car with the internet path there, it is "Not in range".
  const { paired, open, tried, ecu } = direct;
  const wifi = open ? OK
    : !paired ? { state: hubOk ? 'idle' : 'fail', note: 'Not paired' }
      : hubOk && tried ? { state: 'idle', note: 'Not in range' }
        : { state: hubOk ? 'idle' : 'wait', note: 'Searching…' };
  const ecuRow = () => {
    if (hubOk && b && online) {
      if (b.ecu_port === 'absent') return { state: 'fail', note: 'Unplugged' };
      if (live?.state === 'wait' && live.note.startsWith('Busy')) return live;   // a sync pauses the readings
      if (!ecuOn) return { state: 'idle', note: 'No connection' };
      return live || { state: 'wait', note: 'Starting…' };
    }
    if (open) {
      return /^no ECU/.test(ecu || '') ? { state: 'fail', note: 'Unplugged' }
        : /polling|reading identity|pinging|starting/.test(ecu || '') ? { state: 'wait', note: 'Starting…' }
          : { state: 'idle', note: 'No connection' };
    }
    return { state: 'skip', note: 'Can\'t check' };
  };
  return [
    { id: 'hub', group: 'phone', text: 'Internet', ...(PHONE[server] || PHONE.offline) },
    { id: 'direct', group: 'phone', text: 'Local Wi-Fi to Bridge', ...wifi },
    { id: 'bridge', group: 'bridge', text: 'Internet', ...net },
    { id: 'ecu', group: 'bridge', text: 'ECU', ...ecuRow() },
  ];
}

// The one thing to do next, shown under the checklist ('' when there is nothing to do: all
// ticked, still connecting, a job running, or the sign-in button already says it). rows: statusRows;
// phoneOnline as there. Direct up (the phone and the Bridge on the same Wi-Fi) makes the internet
// rows beside the point, so only the ECU can need something then.
export const STEPS = {
  hotspot: 'Turn on your phone\'s hotspot so the Bridge can join it',
  pair: 'Connect this phone to the internet once to pair it with the Bridge',
  bridge: 'Turn the ECU on, with Wi-Fi or your phone\'s hotspot in range of the Bridge',
  plug: 'Plug the Bridge into the ECU\'s USB port',
  key: 'Turn the ECU on',
};
export function nextStep(rows, { phoneOnline = false } = {}) {
  const r = Object.fromEntries(rows.map((x) => [x.id, x]));
  const local = r.direct?.state === 'ok';
  if (!local) {
    if (r.hub.state === 'half' || r.hub.state === 'wait') return '';
    if (r.hub.state === 'fail') {
      if (r.direct.note !== 'Not paired') return STEPS.hotspot;
      return phoneOnline ? '' : STEPS.pair;              // server down: pairing waits for it
    }
    if (r.bridge.state === 'fail') return STEPS.bridge;  // never connected, or offline now
  }
  if (r.ecu.note === 'Unplugged') return STEPS.plug;
  if (r.ecu.state === 'idle') return STEPS.key;
  return '';
}

// Whether the internet path is all there: this phone, the Bridge, and the ECU (Direct aside).
export const internetPath = (rows) => rows.every((r) => r.id === 'direct' || r.state === 'ok');

// Whether the panels show, dim (old values, still on screen) or give way to the checklist, and the
// checklist's ECU row once the ECU is answering.
//   ageS: seconds since the newest reading (null: none); fast: a live view is running, so
//   readings should come 5 a second; hbS: the heartbeat interval; busy: label of another job the
//   box is doing; problem: the last live view failed; starting: a live view is queued or just
//   started.
export function liveState({ ageS, fast, hbS = 10, busy = '', problem = false, starting = false }) {
  const waitRow = busy ? { state: 'wait', note: `Busy: ${busy}` }
    : problem ? { state: 'wait', note: 'Retrying…' }
      : starting ? { state: 'wait', note: 'Starting…' }
        : null;
  const noData = { state: 'fail', note: 'No data' };
  if (ageS === null || ageS === undefined) return { mode: 'status', row: waitRow || noData };
  const dimS = fast ? 5 : 1.5 * hbS;
  const hideS = fast ? 30 : Math.max(30, 3 * hbS);
  if (ageS <= dimS) return { mode: 'panels', row: { state: 'ok', note: '' } };
  if (ageS <= hideS) return { mode: 'dim', row: { state: 'ok', note: '' } };
  return { mode: 'status', row: waitRow || noData };
}

// One reading from several ({t, key: value}: the heartbeat's live values, the newest trend sample,
// the newest fast sample): the newest one, with any key it lacks taken from the others when they
// are at most maxAgeMs older (a trend row carries fewer keys than a heartbeat). null when none.
export function mergeReadings(rows, maxAgeMs = 30_000) {
  const ok = rows.filter((r) => r?.t && !Number.isNaN(new Date(r.t).getTime()))
    .sort((a, b) => new Date(a.t) - new Date(b.t));
  if (!ok.length) return null;
  const newest = new Date(ok[ok.length - 1].t).getTime();
  return Object.assign({}, ...ok.filter((r) => newest - new Date(r.t).getTime() <= maxAgeMs), { t: ok[ok.length - 1].t });
}

// The playback clock for live readings, which arrive in batches (10 readings every 2 s): it runs
// in real time a little behind the newest reading, so the needles move smoothly instead of jumping
// once per batch. Never ahead of the newest reading; when it falls too far behind (a late batch, or
// the first one), it jumps to leadMs behind.
export function nextPlayhead(prev, dtMs, newestMs, leadMs = 2000, maxLagMs = 2 * leadMs + 500) {
  if (!Number.isFinite(newestMs)) return null;
  let p = Number.isFinite(prev) ? prev + dtMs : newestMs - leadMs;
  if (p > newestMs) p = newestMs;
  if (p < newestMs - maxLagMs) p = newestMs - leadMs;
  return p;
}

// The values at time tMs from rows [{t, key: value}] sorted oldest first (tms: each row's time in
// ms, the same length), straight-line between the two readings either side. Before the first
// reading: the first; after the last: the last.
export function sampleAt(rows, tms, tMs) {
  if (!rows.length) return null;
  if (tMs <= tms[0]) return rows[0];
  const n = rows.length;
  if (tMs >= tms[n - 1]) return rows[n - 1];
  let lo = 0, hi = n - 1;
  while (hi - lo > 1) { const mid = (lo + hi) >> 1; if (tms[mid] <= tMs) lo = mid; else hi = mid; }
  const a = rows[lo], b = rows[hi];
  const f = (tMs - tms[lo]) / Math.max(1, tms[hi] - tms[lo]);
  const out = { t: new Date(tMs).toISOString() };
  for (const k of Object.keys(a)) {
    if (k === 't') continue;
    out[k] = typeof a[k] === 'number' && typeof b[k] === 'number' ? a[k] + (b[k] - a[k]) * f : a[k];
  }
  return out;
}

// The live chart's readings: only the new rows since the last send, or all of them (reset) when the
// rows don't carry on from what was sent.
// sent: the newest row time sent before (null: none yet); rows, tms: the rows and their times in ms,
// oldest first. They carry on only when the row last sent is still there, at exactly that time: the
// same buffer grown at its end (and maybe trimmed at its start). Anything else is other rows (another
// Bridge, a new live session, a buffer started again) and is sent whole, so the chart never joins two
// cars' data. Nothing sent yet, no rows, or rows that end before the last sent: reset too.
export function rowsToSend(sent, rows, tms) {
  const newest = tms.length ? tms[tms.length - 1] : null;
  let from = tms.length;
  if (sent !== null && newest !== null) {
    let lo = 0, hi = tms.length;                     // the first row newer than the one sent
    while (lo < hi) { const mid = (lo + hi) >> 1; if (tms[mid] <= sent) lo = mid + 1; else hi = mid; }
    from = lo;
  }
  const reset = sent === null || newest === null || from === 0 || tms[from - 1] !== sent;
  return { rows: reset ? rows : rows.slice(from), reset, sent: newest };
}

// The web app version. scripts/deploy.sh raises the last number on every deploy that
// changes hub/src. Never edit by hand.
export const WEB_VERSION = '1.4.194';

// What Steve feels, timed in the app and sent to the hub's metrics (component 'web'): one helper
// for every timing (CLAUDE.md "Code quality"). Rows are batched and sent every 15 s, and when the
// page is hidden. Never throws; a lost batch is only lost timings.
//
//   const t = perfStart('web.command', id);  t.step('queued');  ...  t.end('ok');
import { WEB_VERSION } from 'tl-mod:7';

const FLUSH_MS = 15000;
const MAX_ROWS = 50;
let send = null;              // (rows) => Promise, set by initPerf
const rows = [];

export function perfStart(op, corr) {
  const t0 = performance.now();
  const startedAt = new Date().toISOString();
  let last = t0;
  const steps = {};
  let done = false;
  return {
    step(name) {
      const now = performance.now();
      if (!(name in steps)) steps[name] = Math.round(now - last);
      last = now;
    },
    has(name) { return name in steps; },
    end(result = 'ok', extra = {}) {
      if (done) return;
      done = true;
      queue({ op, corr: corr == null ? null : String(corr), started_at: startedAt,
        duration_ms: Math.round(performance.now() - t0), steps, result, ...extra });
    },
  };
}

function queue(row) {
  rows.push({ ...row, version: WEB_VERSION });
  if (rows.length >= MAX_ROWS) flush();
}

export function flush() {
  if (!send || !rows.length) return;
  const batch = rows.splice(0, MAX_ROWS);
  send(batch).catch(() => {});
}

// Page load from the browser's own navigation timing, once.
function pageLoad() {
  const n = performance.getEntriesByType?.('navigation')?.[0];
  if (!n || !n.loadEventEnd) return;
  queue({ op: 'web.page_load', started_at: new Date(performance.timeOrigin).toISOString(),
    duration_ms: Math.round(n.loadEventEnd), result: 'ok',
    steps: { dns: Math.round(n.domainLookupEnd - n.domainLookupStart), connect: Math.round(n.connectEnd - n.connectStart),
      response: Math.round(n.responseEnd - n.requestStart), dom: Math.round(n.domContentLoadedEventEnd - n.responseEnd),
      load: Math.round(n.loadEventEnd - n.domContentLoadedEventEnd) } });
}

// How long until the first gauge showed a reading, once per page (js/dash/car_tab.js onFirstGauge: the dash's frame reports its first painted reading): the HTML,
// then the scripts loading and starting (to DOMContentLoaded), then the first reading drawn. corr
// says how the page came: test or car, and how the offline copy served it (sw.js: saved, network,
// test, offline; none without the worker). bytes: what came over the network for it.
export function firstGauge(corr) {
  const n = performance.getEntriesByType?.('navigation')?.[0], now = performance.now();
  const html = n?.responseEnd || 0, dom = n?.domContentLoadedEventEnd || now;
  const bytes = [n, ...(performance.getEntriesByType?.('resource') || [])].reduce((t, e) => t + (e?.transferSize || 0), 0);
  queue({ op: 'web.first_gauge', corr, started_at: new Date(performance.timeOrigin).toISOString(), duration_ms: Math.round(now),
    result: 'ok', bytes, steps: { html: Math.round(html), scripts: Math.round(Math.max(0, dom - html)), gauge: Math.round(Math.max(0, now - dom)) } });
}

export function initPerf(sender) {
  send = sender;
  if (document.readyState === 'complete') pageLoad();
  else window.addEventListener('load', () => setTimeout(pageLoad, 0), { once: true });
  setInterval(flush, FLUSH_MS);
  document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'hidden') flush(); });
}

// The app's side of a dash's frame (../ecuai/docs/plan-dashes.md, "The bridge"): makes the
// sandboxed frame, hands it one MessageChannel, sends it the package and the data, and checks every
// message that comes back, within limits (limits.js): a frame that floods the bridge is stopped.
// Nothing a frame can send leads anywhere but showing or hiding the tab bar, the gear for its own
// settings, a display unit, its small store and read-only trend data: no plans, approvals, commands or
// writes. A dash that lists the tune feed gets a few named values from the car's tune (tune_values.js), read-only.
// A frame that goes silent for 5 s while on screen (watch.js: time the app itself was stalled
// doesn't count), or navigates itself (blocked by the app's frame-src, and caught here by the frame's
// second load), is removed.
// Feeds wait for the dash: nothing but init goes to the frame until it says `ready` (its mount has
// run, so its handlers are there); until then the newest message of each kind is kept and sent the
// moment it is ready (the whole live chart, the trend, the newest reading, the units and the tab bar).
import { srcdoc } from 'tl-mod:0';
import { loadPackage, kitCss, dashFonts } from 'tl-mod:3';
import { tokenBucket, jsonSize, cleanStore, checkBeat, requestGate } from 'tl-mod:4';
import { watchStep, watchBeat } from 'tl-mod:5';
import { rowsToSend } from 'tl-mod:6';
import { perfStart } from 'tl-mod:8';

const LAG_EVERY_MS = 60_000, ROWS_EVERY_MS = 100, TREND_EVERY_MS = 30_000;
// Far above what a real dash needs (ours: a heartbeat a second, a store write when a box changes, a
// few history requests a minute), far below what would slow the app.
const MESSAGES = [50, 300], ERRORS = [0.5, 5], NAVS = [5, 10], UNITS = [2, 4];   // [per second, burst]
const STORE = { bytes: 16_384, keys: 64, writeMs: 3000 };
const TREND = { perMin: 20, cacheMs: 30_000, queue: 8 };
const live = new Set();
let page = null;

// Every frame's heartbeat, checked once a second, only while it is on screen.
setInterval(() => {
  const now = Date.now();
  for (const g of live) {
    g.watch = watchStep(g.watch, now, g.onScreen());
    if (g.watch.dead) g.fail('stopped answering');
  }
}, 1000);
addEventListener('pagehide', () => { for (const g of live) g.flush(); });   // the store is written every few seconds: and now

// ref: a built-in id or a user package. opts: units, tune (tune_values.js: for a dash with the tune feed), bridge, history() (the phone's history snapshot), store ({load(), save(obj)}: this
// dash's own store, chosen by the caller), params (a test address's parameters for the dash, or null),
// request(what, args) (a promise; 'trend' only), onNav(show) (the dash asks for the tab bar, or to hide
// it), onGear (the dash has settings of its own: the app shows its gear), onUnit(kind, key) (it asks for a display unit: untrusted, the caller checks), onFirstPaint (its
// first reading is on screen), onScreen() (the dash is showing: the watchdog runs only then; default
// always), onReady, onFail(reason, {load}) (load: its files couldn't be loaded, as opposed to its code
// failing), onError (an error the dash's code threw), onBeat (each heartbeat: {lag, lagMax, fps}).
export function createDashFrame(ref, opts) {
  const el = document.createElement('iframe');
  el.className = 'dash-frame';
  el.setAttribute('sandbox', 'allow-scripts');
  el.title = 'Dash';
  let port = null, loads = 0, lagAt = Date.now(), lagSum = 0, lagN = 0, lagMax = 0, fpsSum = 0, fpsN = 0, id = typeof ref === 'string' ? ref : ref.id;
  let navShown = true, rowsSent = null, rowsAt = -Infinity, trendSent = null, trendAt = 0;
  const pending = new Map();   // kind -> send(): the newest of each, sent when the dash is ready
  const messages = tokenBucket(...MESSAGES), errors = tokenBucket(...ERRORS), navs = tokenBucket(...NAVS), unitAsks = tokenBucket(...UNITS), trend = requestGate(TREND);
  // The dash's store lives here while it runs and goes to the phone at most every few seconds.
  const kept = cleanStore(opts.store?.load(), STORE.bytes, STORE.keys);
  const mem = Object.assign(Object.create(null), kept), sizes = new Map();
  let used = 0, dirty = false, timer = 0;
  for (const k of Object.keys(mem)) { sizes.set(k, k.length + 4 + jsonSize(mem[k], STORE.bytes)); used += sizes.get(k); }
  const post = (m) => { if (port && !g.failed) port.postMessage(m); };
  // Before init nothing is kept (init carries the units and the tab bar; the feeds come again each frame).
  const keep = (kind, send) => { if (port && !g.failed) pending.set(kind, send); };
  const whenReady = (kind, send) => { if (g.ready) send(); else keep(kind, send); };
  function sendRows(rows, tms, end) {
    const out = rowsToSend(rowsSent, rows, tms);
    post({ type: 'rows', rows: out.rows, reset: out.reset, end: end ?? out.sent ?? Date.now() });
    rowsSent = out.sent;
    rowsAt = performance.now();
  }
  function sendTrend(rows, now) { post({ type: 'trend', rows }); trendSent = rows; trendAt = now; }
  const g = {
    el, id, manifest: null, gear: false, ready: false, started: false, painted: false, failed: null, watch: null,
    onScreen: () => !document.hidden && (opts.onScreen ? !!opts.onScreen() : true),
    reading(v, t, extra) { whenReady('r', () => post({ type: 'r', v, t, at: performance.timeOrigin + performance.now(), ...extra })); },
    nav(shown) { navShown = !!shown; whenReady('nav', () => post({ type: 'nav', shown: navShown })); },
    units(units) { opts.units = units; whenReady('units', () => post({ type: 'units', units })); },
    // A press somewhere in the app outside the frame (the tab bar): a dash may close a menu.
    outside() { if (g.ready) post({ type: 'outside' }); },
    // The gear was tapped: the dash opens its own settings.
    openSettings() { if (g.ready) post({ type: 'settings' }); },
    // The car's tune values changed (a new tune read).
    tune(values) { opts.tune = values; if (g.wants('tune')) whenReady('tune', () => post({ type: 'tune', tune: values })); },
    // The live chart's rows (rows oldest first, tms their times in ms, end the playback clock): only the
    // new ones, every 100 ms at most, all of them again when they don't carry on (rowsToSend).
    rows(rows, tms, end) {
      if (!g.wants('rows')) return;
      if (!g.ready) { keep('rows', () => sendRows(rows, tms, end)); return; }
      if (performance.now() - rowsAt >= ROWS_EVERY_MS) sendRows(rows, tms, end);
    },
    // The 2-hour trend: when it changes, and every 30 s (for how long nothing has come in).
    trend(rows) {
      if (!g.wants('trend')) return;
      const now = Date.now();
      if (!g.ready) keep('trend', () => sendTrend(rows, now));
      else if (trendSent !== rows || now - trendAt > TREND_EVERY_MS) sendTrend(rows, now);
    },
    wants: (feed) => !!g.manifest?.feeds.includes(feed),
    flush() { clearTimeout(timer); timer = 0; if (dirty) { dirty = false; opts.store?.save({ ...mem }); } },
    fail(reason, kind) {
      if (g.failed) return;
      g.failed = reason;
      live.delete(g);
      pending.clear();
      g.flush();
      try { port?.close(); } catch { /* closed */ }
      el.removeAttribute('srcdoc');
      el.src = 'about:blank';
      opts.onFail?.(reason, { load: kind === 'load' });
    },
    destroy() { live.delete(g); g.flush(); g.failed ||= 'closed'; try { port?.close(); } catch { /* closed */ } el.remove(); },
  };

  function onMessage(e) {
    if (g.failed) return;
    const now = Date.now();
    if (!messages.take(now)) { g.fail('sent too many messages'); return; }
    const m = e.data;
    if (!m || typeof m !== 'object') return;
    if (m.type === 'hb') {
      g.watch = watchBeat(g.watch, now);
      const b = checkBeat(m);
      opts.onBeat?.({ lag: b.lag, lagMax: b.lagMax, fps: b.fps });
      if (b.lag !== null && b.n > 0) { lagSum += b.lag * b.n; lagN += b.n; lagMax = Math.max(lagMax, b.lagMax); }
      if (b.fps !== null) { fpsSum += b.fps; fpsN++; }
      // Paint lag with the frame rate beside it: an iPhone may hold a cross-origin frame to 30 fps.
      if (lagN && now - lagAt > LAG_EVERY_MS) {
        const steps = { max: lagMax, ...(fpsN ? { fps: Math.round(fpsSum / fpsN) } : {}) };
        perfStart('web.dash_lag', id).end('ok', { duration_ms: Math.round(lagSum / lagN), steps });
        lagAt = now; lagSum = 0; lagN = 0; lagMax = 0; fpsSum = 0; fpsN = 0;
      }
    } else if (m.type === 'ready') {
      if (g.ready) return;
      g.ready = true;
      for (const send of pending.values()) send();
      pending.clear();
      opts.onReady?.(g);
    }
    else if (m.type === 'failed') { const text = said(m); opts.onError?.(text); g.fail(`its code failed while starting: ${text}`); }
    else if (m.type === 'gear') { if (!g.gear) { g.gear = true; opts.onGear?.(); } }
    else if (m.type === 'nav') { if (navs.take(now)) opts.onNav?.(m.show !== false); }
    else if (m.type === 'unit') { if (unitAsks.take(now)) opts.onUnit?.(m.kind, m.key); }
    else if (m.type === 'painted') { if (!g.painted) { g.painted = true; opts.onFirstPaint?.(); } }
    else if (m.type === 'error' && typeof m.message === 'string') { if (errors.take(now)) opts.onError?.(said(m)); }
    else if (m.type === 'request' && Number.isInteger(m.id) && m.id >= 0) answer(m);
  }
  function said(m) {
    const text = typeof m.message === 'string' ? m.message.slice(0, 300) : 'unknown error';   // never String(): a dash's object could throw here
    console.warn(`dash ${id}:`, text);
    return text;
  }

  // One store key: plain JSON data only, sized before anything copies it; undefined removes the key.
  function storeSet(k, v) {
    if (typeof k !== 'string' || !k || k.length > 40) return 'bad key';
    const others = used - (sizes.get(k) ?? 0);
    if (v === undefined) { delete mem[k]; sizes.delete(k); used = others; }
    else {
      if (!sizes.has(k) && sizes.size >= STORE.keys) return 'too many keys';
      const size = jsonSize(v, STORE.bytes - others - k.length - 4);
      if (size < 0) return 'store full, or not plain data';
      mem[k] = v; sizes.set(k, k.length + 4 + size); used = others + sizes.get(k);
    }
    dirty = true;
    timer ||= setTimeout(g.flush, STORE.writeMs);
    return null;
  }

  function answer(m) {
    const reply = (result, error) => { if (m.id) post({ type: 'reply', id: m.id, result, error }); };
    if (m.what === 'store') { const err = storeSet(m.args?.k, m.args?.v); return err ? reply(null, err) : reply(true); }
    if (m.what === 'trend' && opts.request) {
      if (jsonSize(m.args, 1000) < 0) return reply(null, 'bad request');
      trend.run(JSON.stringify(m.args), () => opts.request('trend', m.args))
        .then((r) => reply(r), (err) => reply(null, String(err?.message || err).slice(0, 200)));
      return;
    }
    reply(null, 'unknown request');
  }

  (async () => {
    // The fonts don't hold the start up: the dash draws with the fallback until they arrive (below).
    const fonts = dashFonts();
    const [pkg, html] = await Promise.all([loadPackage(ref), page ??= srcdoc()]);
    // The kit's styles only for a built-in: an installed package carries its own (its manifest's styles).
    const css = pkg.builtin ? `${await kitCss()}\n${pkg.css}` : pkg.css;
    if (g.failed) return;
    g.manifest = pkg.manifest;
    id = pkg.manifest.id;
    g.id = id;
    el.title = pkg.manifest.name;
    el.addEventListener('load', () => {
      if (++loads > 1) { g.fail('tried to leave its page'); return; }
      const ch = new MessageChannel();
      port = ch.port1;
      port.onmessage = onMessage;
      el.contentWindow.postMessage('tl-init', '*', [ch.port2]);
      g.watch = null;
      g.started = true;
      live.add(g);
      post({
        type: 'init', modules: pkg.modules.map((x) => ({ code: x.code, imports: x.imports })), css,
        units: opts.units, tune: pkg.manifest.feeds.includes('tune') ? opts.tune ?? null : null,
        bridge: opts.bridge, params: opts.params ?? null, store: { ...mem }, nav: navShown,
        history: pkg.manifest.feeds.includes('history') ? opts.history?.() : null,
      });
      fonts.then((list) => post({ type: 'fonts', fonts: list }));
    });
    el.srcdoc = html;
  })().catch((err) => g.fail(String(err?.message || err), 'load'));
  return g;
}

// Per-device settings in localStorage. Reads and writes never throw: in private mode, with site
// data blocked, or outside a browser, a read gives null and a write is dropped.
export const store = {
  get(k) { try { return localStorage.getItem(k); } catch { return null; } },
  set(k, v) { try { localStorage.setItem(k, v); } catch { /* private mode */ } },
};

// Display units: the choices for each kind of reading, the conversion from the base unit the car
// sends (kPa, deg C, km/h, lambda), and the dial range in the chosen unit. Values, zones and valid
// ranges stay in base units everywhere else; only what is shown is converted. The choice is per
// device (localStorage), and a change tells the listeners so open gauges rebuild.
import { store } from 'tl-mod:10';

export const STOICH = 14.7;          // petrol: AFR = lambda x 14.7

const same = (v) => v;
// kind: { name (the Settings row), def (the default option), options: { key: { name (the
// select's text), unit (after the number), dp (decimals), from (base unit to this one), word
// (optional: replaces "Lambda" in a channel's name, so "Lambda 1" shows as "AFR 1") } } }.
// The first option of each kind is its base unit.
export const UNITS = {
  pressure: { name: 'Pressure', def: 'psi', options: {
    kpa: { name: 'kPa', unit: 'kPa', dp: 0, from: same },
    bar: { name: 'bar', unit: 'bar', dp: 2, from: (v) => v / 100 },
    psi: { name: 'psi', unit: 'psi', dp: 0, from: (v) => v * 0.1450377 },
  } },
  temperature: { name: 'Temperature', def: 'f', options: {
    c: { name: '°C', unit: '°C', dp: 0, from: same },
    f: { name: '°F', unit: '°F', dp: 0, from: (v) => v * 9 / 5 + 32 },
  } },
  speed: { name: 'Speed', def: 'mph', options: {
    kmh: { name: 'km/h', unit: 'km/h', dp: 0, from: same },
    mph: { name: 'mph', unit: 'mph', dp: 0, from: (v) => v / 1.609344 },
  } },
  mixture: { name: 'Mixture', def: 'lambda', options: {
    lambda: { name: 'Lambda', unit: '', dp: 2, from: same },
    afr: { name: 'AFR', unit: 'AFR', dp: 1, from: (v) => v * STOICH, word: 'AFR' },
  } },
};

const KEY = 'ecuai-units';
const listeners = new Set();
let saved = null;                    // { kind: option key } as stored, read once

// The chosen option key for every kind, defaults filled in and unknown keys dropped.
export function units(raw) {
  if (raw === undefined) {
    if (saved === null) { try { saved = JSON.parse(store.get(KEY)) || {}; } catch { saved = {}; } }
    raw = saved;
  }
  return Object.fromEntries(Object.entries(UNITS).map(([kind, u]) => [kind, u.options[raw?.[kind]] ? raw[kind] : u.def]));
}

// In a dash's frame (no storage of its own): the choices the app sends.
export function useUnits(raw) { saved = { ...(raw || {}) }; }

export function setUnit(kind, key) {
  if (!UNITS[kind]?.options[key]) return;
  saved = { ...units(), [kind]: key };
  store.set(KEY, JSON.stringify(saved));
  for (const fn of listeners) fn(units());
}

// fn(choices) on every change; returns a function that stops it.
export function onUnitsChange(fn) {
  listeners.add(fn);
  return () => listeners.delete(fn);
}

// The option shown for a kind: { key, name, unit, dp, from, base }. choices: units() by default.
export function unitFor(kind, choices = units()) {
  const u = UNITS[kind];
  const key = u.options[choices[kind]] ? choices[kind] : u.def;
  return { key, ...u.options[key], base: key === Object.keys(u.options)[0] };
}

// A base-unit value in the chosen unit, and as text with that unit's decimals.
export const convert = (kind, v, choices) => unitFor(kind, choices).from(v);
export const format = (kind, v, choices) => { const u = unitFor(kind, choices); return u.from(v).toFixed(u.dp); };

// A round dial step near x: 1, 2 or 5 times a power of ten, the nearest on a log scale.
export function niceStep(x) {
  const p = 10 ** Math.floor(Math.log10(x));
  const f = x / p;
  return +((f < Math.SQRT2 ? 1 : f < Math.sqrt(10) ? 2 : f < Math.sqrt(50) ? 5 : 10) * p).toPrecision(6);
}

// A dial from min to max (display units): about six round steps, the ends on a step.
export function dialRange(min, max) {
  const step = niceStep((max - min) / 6);
  const at = (v) => +(Math.round(v / step) * step).toPrecision(6);
  return { min: at(min), max: at(max), step };
}

// The car's live channels, as true for any car: label, short name, unit, decimals, how a value
// converts for display (kind, units.js), the icon a big-number box shows, and a plain scale (min, max,
// the dial's step) so a dial or chart can be drawn at all. Keys are the Bridge's live keys (ecuai
// carbox core/ecu_state.c ECU_LIVE, the hub's LIVE_KEYS). A value the ECU can't give (a sensor not
// wired, or not in its live block) simply shows "-".
// There are no limits here: no red or amber zones, no valid range from one car's sensor calibration,
// no notes about one engine. Those belong to a dash (the built-in dash's ranges.js), which applies
// its own with useChannels(ranges) at mount, so every kit module in its frame sees them. Outside a dash (the app's own pages) the table stays as it is.
// Values, zones, valid ranges and dials are in the base unit the car sends (kPa, deg C, lambda);
// kind says how a channel converts for display, and shown() gives it in the chosen unit. unit is the
// base unit's label (the raw ecu.live table on the Activity tab shows base values).
// What a dash's ranges may add to a channel:
//   red, warn, cold: zones, [lo, hi] pairs; a value inside a red zone shows red, inside a warn zone
//     amber; cold is where the engine is still warming up (the dial's yellow ticks).
//   valid: [lo, hi]; a reading outside it is not a reading (a wideband controller parked at 0 V or
//     5 V while off or heating, an open-circuit temperature sensor at -40) and shows as "-".
//   note: a second line on a dial (which cylinders a wideband reads).
//   trend: the value panel's history: span, the least height of its chart; valid, what it counts.
//   shift (rpm): where the Pull view's shift light comes on.
//   cooling: [amber, red] in deg C a minute: a temperature falling faster than this warns.
//   vdo: the big-number box also carries a dial (Vintage 3D shows it); dialLabel: the name on the
//     dial's face, with {unit} where the unit goes; dial.bare, dial.bareFirst: labels a real dial
//     leaves off.
import { unitFor, dialRange } from 'tl-mod:11';

export const CHANNELS = {
  rpm:        { label: 'RPM', unit: '', dp: 0, steady: { step: 50, fastStep: 250, fastRate: 1500 }, min: 0, max: 8000, dial: { step: 1000, scale: 1000, note: 'x1000' }, icon: 'tach' },
  lambda1:    { kind: 'mixture', label: 'Lambda 1', unit: '', dp: 2, min: 0.6, max: 1.4, dial: { step: 0.2, scale: 1 }, icon: 'lambda' },
  lambda2:    { kind: 'mixture', label: 'Lambda 2', unit: '', dp: 2, min: 0.6, max: 1.4, dial: { step: 0.2, scale: 1 }, icon: 'lambda' },
  lambda_target: { kind: 'mixture', label: 'Lambda target', short: 'Lambda T', unit: '', dp: 2, min: 0.6, max: 1.4, dial: { step: 0.2, scale: 1 }, icon: 'lambda' },
  ect_c:      { kind: 'temperature', label: 'Head temp', unit: '°C', dp: 0, min: 0, max: 250, dial: { step: 50, scale: 1 }, icon: 'head' },   // named for the sensor: the head on an air-cooled engine. A water-cooled car's profile will name it Coolant temp
  iat_c:      { kind: 'temperature', label: 'Intake air', short: 'Intake', unit: '°C', dp: 0, min: -10, max: 80, dial: { step: 10, scale: 1 }, icon: 'air' },
  map_kpa:    { kind: 'pressure', label: 'MAP', unit: 'kPa', dp: 0, min: 0, max: 110, dial: { step: 10, scale: 1 }, icon: 'gauge' },
  tps_pct:    { label: 'Throttle', unit: '%', dp: 0, min: 0, max: 100, dial: { step: 20, scale: 1 }, icon: 'throttle' },
  battery_v:  { label: 'Battery', unit: 'V', dp: 1, min: 10, max: 16, dial: { step: 1, scale: 1 }, icon: 'battery' },
  oil_kpa:    { kind: 'pressure', label: 'Oil pressure', short: 'Oil press', unit: 'kPa', dp: 0, min: 0, max: 700, dial: { step: 100, scale: 1 }, icon: 'oilp' },
  fuel_kpa:   { kind: 'pressure', label: 'Fuel pressure', short: 'Fuel press', unit: 'kPa', dp: 0, min: 0, max: 400, dial: { step: 50, scale: 1 }, icon: 'gauge' },
  ign_deg:    { label: 'Ignition', unit: '°', dp: 1, min: -10, max: 50, dial: { step: 10, scale: 1 }, icon: 'gauge' },
  speed_kmh:  { kind: 'speed', label: 'Speed', unit: 'km/h', dp: 0, min: 0, max: 240, dial: { step: 20, scale: 1 }, icon: 'gauge', phone: true },   // the phone's GPS (sensors.js)
  oil_temp_c: { kind: 'temperature', label: 'Oil temp', unit: '°C', dp: 0, min: 40, max: 150, dial: { step: 20, scale: 1 }, icon: 'oil' },
};

// A dash's ranges onto the table every kit module reads, in place (a dash's frame has its own copy of
// this module): { key: { field: value } } for channels the table has; dial and trend are merged, every
// other field replaces the one before. Unknown channels are ignored.
export function useChannels(ranges) {
  for (const [key, o] of Object.entries(ranges || {})) {
    const ch = Object.hasOwn(CHANNELS, key) ? CHANNELS[key] : null;
    if (!ch || !o || typeof o !== 'object') continue;
    Object.assign(ch, o, o.dial ? { dial: { ...ch.dial, ...o.dial } } : {}, o.trend ? { trend: { ...ch.trend, ...o.trend } } : {});
  }
}

// A reading as a number, or null when there is none or it is outside the channel's valid range.
export function reading(ch, v) {
  if (typeof v !== 'number' || !Number.isFinite(v) ) return null;
  if (ch?.valid && (v < ch.valid[0] || v > ch.valid[1])) return null;
  return v;
}

// Where a channel counts as warmed up (the top of its cold zone, base units), or null.
export const warmAt = (ch) => ch?.cold?.at(-1)?.[1] ?? null;

// 'red', 'warn' or '' for a value of a channel.
export function zoneOf(ch, v) {
  if (reading(ch, v) === null || !ch) return '';
  const inside = (zones) => (zones || []).some(([lo, hi]) => v >= lo && v <= hi);
  return inside(ch.red) ? 'red' : inside(ch.warn) ? 'warn' : '';
}

const same = (v) => v;
const unitOf = (ch, choices) => (ch?.kind ? unitFor(ch.kind, choices) : null);

// A value as text in the chosen unit with its decimals, or '-' when there is none.
export function fmt(ch, v, choices) {
  const x = reading(ch, v);
  if (x === null) return '-';
  const u = unitOf(ch, choices);
  return u ? u.from(x).toFixed(u.dp) : x.toFixed(ch?.dp ?? 1);
}

// The most characters a channel's value ever takes when shown (its range's ends), so a box can be that
// wide always and nothing beside it moves when the value grows a digit (99 to 100 psi).
export function maxChars(base, choices) {
  return Math.max(1, ...[base.min, base.max, (base.min + base.max) / 2].map((v) => fmt({ ...base, valid: undefined }, v, choices).length));
}

// A channel as shown in the chosen units (units.js units() by default): name, unit label, decimals,
// dial range and round step, and zones all converted; value(v) gives a base reading in the
// chosen unit (null when there is none), text(v) the same as fmt. The base unit keeps the
// channel's own dial. zoneOf() still takes the base channel and base value.
export function shown(ch, choices) {
  const u = unitOf(ch, choices);
  const conv = u ? u.from : same;
  const r = !u || u.base ? { min: ch.min, max: ch.max, dial: ch.dial } : dialRange(conv(ch.min), conv(ch.max));
  const zones = (zs) => zs?.map(([lo, hi]) => [conv(lo), conv(hi)]);
  return {
    ...ch,
    label: u?.word ? ch.label.replace(/^Lambda/, u.word) : ch.label,
    unit: u ? u.unit : ch.unit, dp: u ? u.dp : ch.dp,
    min: r.min, max: r.max, dial: r.dial || { ...ch.dial, step: r.step, scale: 1 },
    red: zones(ch.red), warn: zones(ch.warn), cold: zones(ch.cold),
    value: (v) => { const x = reading(ch, v); return x === null ? null : conv(x); },
    text: (v) => fmt(ch, v, choices),
  };
}

// The live chart (the last minute, 5 readings a second) and the trend chart (2 hours of
// heartbeats). axis 'l' or 'r'. split: which series go in each of the two charts when held upright.
export const CHARTS = {
  live: { title: 'Last minute', series: [['rpm', 'l', 'rpm'], ['tps_pct', 'r', 'tps'], ['map_kpa', 'r', 'map']], split: [[0], [1, 2]] },
  trend: { title: 'Last 2 hours', series: [['ect_c', 'l', 'ect'], ['iat_c', 'l', 'iat'], ['oil_temp_c', 'l', 'oil']], split: [[0, 2], [1]] },
};

// The value panels' stored history, fetched when a view first needs it and kept for a while: the
// last hour (the trends function) and the last 30 days by day (trend_days). Views read it every
// frame, so a read never waits: it gives what is held and refreshes it behind the scenes.
import { CHANNELS, reading } from 'tl-mod:12';

const KEEP_MS = { hour: 30_000, days: 300_000 };
const held = new Map();
let source = null;   // { call(name, body), bridge() }

export const setTrendSource = (s) => { source = s; held.clear(); };

// One of the two history functions through the source: the app answers a dash frame's request with
// it (js/dash/requests.js); in the frame the dash's own source asks the app.
export function callTrend(name, body) {
  if (!source) return Promise.reject(new Error('no history source'));
  return source.call(name, { ...body, bridge: source.bridge() });
}

// A reading the history should count: valid for the channel and inside its trend.valid.
function counts(key, v) {
  const ch = CHANNELS[key], x = reading(ch, typeof v === 'string' ? Number(v) : v), w = ch.trend?.valid;
  return x !== null && (!w || (x >= w[0] && x <= w[1])) ? x : null;
}

async function fetchKind(kind, key) {
  const bridge = source.bridge();
  if (kind === 'hour') {
    const r = await source.call('trends', { bridge, minutes: 60, fields: [key] });
    return { rows: (r.rows || []).map((x) => ({ t: new Date(x.t).getTime(), v: counts(key, x[key]) })).filter((x) => x.v !== null) };
  }
  const ch = CHANNELS[key], [lo, hi] = ch.trend?.valid || ch.valid || [-1e6, 1e6];
  const r = await source.call('trend_days', { bridge, key, lo, hi });
  return { today: r.today, rows: (r.days || []).map((d) => ({ day: d.day, min: d.min, max: d.max, avg: d.avg, n: Number(d.n) })) };
}

// { rows, today, loaded } for 'hour' or 'days' of a channel.
export function trendData(kind, key) {
  if (!source) return { rows: [], loaded: true };
  const id = `${source.bridge()}:${kind}:${key}`;
  let e = held.get(id);
  if (!e) { e = { rows: [], loaded: false, at: 0, busy: false }; held.set(id, e); }
  if (!e.busy && Date.now() - e.at > KEEP_MS[kind]) {
    e.busy = true;
    fetchKind(kind, key).then((r) => Object.assign(e, r), () => {}).finally(() => { e.busy = false; e.loaded = true; e.at = Date.now(); });
  }
  return e;
}

// What a dash's frame may ask the app for besides its store and the tab bar (frame.js): the stored
// history of one channel, through the hub's two read-only trend functions (kit/trend_data.js), and a
// change of display unit (the person's own setting; our dash: a two-finger tap). Both are untrusted:
// rebuilt from checked fields only.
import { CHANNELS } from 'tl-mod:12';
import { callTrend } from 'tl-mod:13';
import { UNITS, setUnit } from 'tl-mod:11';

const isKey = (k) => typeof k === 'string' && Object.hasOwn(CHANNELS, k);
const num = (v) => typeof v === 'number' && Number.isFinite(v);

// { name, body } for a frame's args, or null.
export function checkTrend(args) {
  const { name, body } = args || {};
  if (name === 'trends') {
    const fields = body?.fields;
    if (!Array.isArray(fields) || !fields.length || fields.length > 13 || !fields.every(isKey)) return null;
    const minutes = Number.isInteger(body.minutes) && body.minutes >= 1 && body.minutes <= 1440 ? body.minutes : 60;
    return { name, body: { minutes, fields: [...fields] } };
  }
  if (name === 'trend_days') {
    if (!isKey(body?.key)) return null;
    return { name, body: { key: body.key, ...(num(body.lo) ? { lo: body.lo } : {}), ...(num(body.hi) ? { hi: body.hi } : {}) } };
  }
  return null;
}

export async function trendRequest(what, args) {
  const q = what === 'trend' ? checkTrend(args) : null;
  if (!q) throw new Error('not allowed');
  const r = await callTrend(q.name, q.body);
  return q.name === 'trends' ? { rows: r?.rows || [] } : { today: r?.today, days: r?.days || [] };
}

// A display unit the dash asks for: only a kind and an option the app's own table has.
export function unitRequest(kind, key) {
  if (typeof kind === 'string' && typeof key === 'string' && Object.hasOwn(UNITS, kind) && Object.hasOwn(UNITS[kind].options, key)) setUnit(kind, key);
}

// Test mode: the Car tab on the simulated drive (sim_feed.js) instead of the car, opened from the URL
// so a dash can be tried on the phone straight after a deploy, with real taps and swipes:
//   index.html?test          the simulated drive
//   &cold                    a cold start: the oil warming up from 15 deg C
//   &cooling                 a cooling drive: the oil starts hot and falls steadily (the glance page's
//                            trend falls, its Now tag under the line)
//   &fresh                   no history drawn yet: the charts start from 0 s, as after opening the app
// Every other parameter goes to the dash as api.params, and means what the dash says it means (the
// built-in dash: left, right, full, level, theme, auto; dashes/tunerloop-dash/start.js). The dash gets
// the phone's store read-only (library.js readOnly): it opens as the phone left it, and nothing chosen
// here is saved.
const HOST = new Set(['test', 'cold', 'cooling', 'fresh', 'safe']);

// null outside test mode, else { cold, cooling, fresh, params: { name: text } } (at most 16 short parameters).
export function parseTest(search) {
  const q = new URLSearchParams(search);
  if (!q.has('test')) return null;
  const params = Object.fromEntries([...q].filter(([k, v]) => !HOST.has(k) && /^[a-z][a-z_]{0,19}$/.test(k) && v.length <= 40).slice(0, 16));
  return { cold: q.has('cold'), cooling: q.has('cooling'), fresh: q.has('fresh'), params };
}

export const testMode = typeof location === 'undefined' ? null : parseTest(location.search);

// A simulated drive for the pages that have no car: the Screens page, Dash Dev and the app's test mode
// (lab/screens.html, lab/dash-dev.html, js/dash/test_mode.js). A loop of idle, full-throttle pulls with shifts, cruising, a
// corner and braking; each step(dt) returns a live reading in base units, phone values included
// (speed_kmh, g_lat, g_long), shaped like the Bridge's readings.
const PLAN = [['idle', 7], ['pull', 9], ['cruise', 6], ['corner', 5], ['cruise', 4], ['pull', 6], ['decel', 5], ['idle', 6]];

// cold: the oil starts at 15 deg C and takes minutes to warm, as on a cold morning. cooling: the oil
// starts hot (108 deg C, under the warning zone) and falls steadily for the whole drive.
export function createSim({ cold = false, cooling = false } = {}) {
  const S = { t: 0, seg: 0, segT: 7, rpm: 900, tps: 0, spd: 0, gx: 0, gy: 0, l1: 1, l2: 1, ect: 150, oilT: cold ? 15 : cooling ? 108 : 70 }, oilTau = cold ? 600 : cooling ? 1500 : 120, oilTo = cooling ? 50 : 95;
  return function step(dt) {
    S.t += dt; S.segT -= dt;
    if (S.segT <= 0) { S.seg = (S.seg + 1) % PLAN.length; S.segT = PLAN[S.seg][1]; }
    const seg = PLAN[S.seg][0], ease = (x, to, tc) => x + (to - x) * (1 - Math.exp(-dt / tc));
    let tps = 0, aLong = 0, aLat = 0.04 * Math.sin(S.t);
    if (seg === 'idle') { S.rpm = ease(S.rpm, 900, 0.5); aLong = S.spd > 0.3 ? -0.35 : 0; }
    else if (seg === 'pull') { tps = 100; S.rpm += (1250 - S.rpm * 0.06) * dt * (S.rpm < 1500 ? 2 : 1); if (S.rpm > 6900) S.rpm = 4300; aLong = Math.max(0.2, 0.62 - S.spd / 210); }
    else if (seg === 'cruise') { tps = 18; S.rpm = ease(S.rpm, 2900, 1.5); aLong = Math.max(-0.08, Math.min(0.08, (80 - S.spd) / 80)); }
    else if (seg === 'corner') { tps = 35; S.rpm = ease(S.rpm, 3800, 1); aLat = 0.68 * Math.sin(Math.PI * (1 - S.segT / 5)); aLong = 0.05; }
    else { S.rpm = Math.max(1200, S.rpm - 900 * dt); aLong = -0.3; }
    S.tps = ease(S.tps, tps, 0.08);
    S.spd = Math.max(0, S.spd + aLong * 35.3 * dt);
    S.gx = ease(S.gx, aLat, 0.08); S.gy = ease(S.gy, aLong, 0.08);
    const map = 25 + 76 * (1 - Math.exp(-S.tps / 13)), tgt = map > 78 ? 1 - 0.12 * Math.min(1, (map - 78) / 20) : 1, cut = S.tps < 2 && S.rpm > 1500;
    S.l1 = ease(S.l1, cut ? 1.3 : tgt * (1 + 0.03 * Math.sin(S.rpm / 1100)), 0.12); S.l2 = ease(S.l2, cut ? 1.3 : tgt * (1.015 + 0.03 * Math.sin(S.rpm / 1100)), 0.14);
    S.ect = ease(S.ect, 150 + 30 * (map / 100) * (S.rpm / 7000) * 3, 40); S.oilT = ease(S.oilT, oilTo, oilTau);
    return {
      rpm: S.rpm, tps_pct: S.tps, map_kpa: map, lambda1: S.l1 + (Math.random() - 0.5) * 0.006, lambda2: S.l2 + (Math.random() - 0.5) * 0.006, lambda_target: tgt,
      ect_c: S.ect, oil_temp_c: S.oilT, iat_c: 32, oil_kpa: (95 + 380 * Math.min(S.rpm, 5200) / 5200) * 0.95, fuel_kpa: 300 + (Math.random() - 0.5) * 4, battery_v: 13.9, ign_deg: 20,
      speed_kmh: S.spd, g_lat: S.gx, g_long: S.gy,
    };
  };
}

// What the hub's trends and trend_days would answer, made up for the lab pages: an hour of readings
// every 10 s and 24 of the last 30 days.
const SIM_BASE = { battery_v: [14.1, 0.2], ect_c: [150, 12], oil_temp_c: [95, 8] };
export async function simTrends(name, body) {
  const [mid, swing] = SIM_BASE[body.key ?? body.fields?.[0]] ?? [50, 5], now = Date.now();
  if (name === 'trends') {
    const key = body.fields[0];
    return { rows: Array.from({ length: 360 }, (_, i) => ({ t: new Date(now - (359 - i) * 10_000).toISOString(), [key]: mid + swing * Math.sin(i / 40) + swing * 0.15 * Math.sin(i * 1.7) })).filter((_, i) => i < 110 || i > 210) };   // the engine off for a while
  }
  const day = (k) => new Date(now - k * 86_400_000).toISOString().slice(0, 10);
  const days = [];
  for (let k = 29; k >= 0; k--) {
    if (k % 5 === 3 || (k > 8 && k < 15)) continue;   // days the car stayed home
    const avg = mid + swing * 0.4 * Math.sin(k / 4) - k * swing * 0.008;
    days.push({ day: day(k), min: avg - swing * (0.7 + 0.3 * Math.sin(k)), max: avg + swing * (0.6 + 0.3 * Math.cos(k)), avg, n: 500 });
  }
  return { today: day(0), days };
}

// Numbers that don't flicker. The shown value moves only when the reading passes 3/4 of a step
// beyond it (hysteresis), at most maxHz times a second, and the step widens while the value sweeps
// fast (RPM in 250s during a pull, 50s when steady). Digits stay put because the dash font's
// figures are tabular (css font-variant-numeric).

// How often the digits may change at most, for every Steady at once while set (Direct's readings come
// 20 a second, so the Car tab lets them change faster then); null: each its own maxHz.
let hzOverride = null;
export const setSteadyHz = (hz) => { hzOverride = hz || null; };

// A needle that doesn't twitch: it keeps its angle until the reading would move it more than band
// degrees (1.5: about 45 RPM on the tach, 4 to 5 px at the tip of a phone-sized dial; 0.6 still
// jittered at idle in the car, 2026-11-21), then goes straight to the new angle.
export const holdAngle = (held, a, band = 1.5) => (held === null || Math.abs(a - held) > band ? a : held);

export class Steady {
  constructor({ step = 1, fastStep = step, fastRate = Infinity, maxHz = 5 } = {}) {
    Object.assign(this, { step, fastStep, fastRate, maxHz });
    this.shown = null; this.prev = null; this.tPrev = 0; this.tChange = -Infinity; this.rate = 0;
  }

  // v: the reading in display units (null for none); now: ms. Returns the value to show, or null.
  update(v, now) {
    if (v === null || v === undefined || !Number.isFinite(v)) { this.shown = null; this.prev = null; return null; }
    const dt = (now - this.tPrev) / 1000;
    if (this.prev !== null && dt > 0.001) this.rate += (Math.abs(v - this.prev) / dt - this.rate) * Math.min(1, dt * 4);
    if (dt > 0.001) { this.prev = v; this.tPrev = now; }
    const step = this.rate > this.fastRate ? this.fastStep : this.step;
    const snap = Math.round(v / step) * step;
    if (this.shown === null) { this.shown = snap; this.tChange = now; }
    else if (Math.abs(v - this.shown) > step * 0.75 && now - this.tChange >= 1000 / (hzOverride || this.maxHz)) { this.shown = snap; this.tChange = now; }
    return this.shown;
  }
}

// A text function for a channel as shown (channels.js shown()): base reading in, steady text out
// ('-' for none). The step is the channel's last shown digit unless the channel sets its own.
export function steadyText(ch, opts = {}) {
  const s = new Steady({ step: 10 ** -ch.dp, ...(ch.steady || {}), ...opts });
  return (v, now = Date.now()) => {
    const x = s.update(ch.value(v), now);
    return x === null ? '-' : x.toFixed(ch.dp);
  };
}

// The Lambda Twin box: both banks on one scale centred on the target, so the driver reads the error,
// not two numbers. Bars grow left for rich and right for lean (+-15 % full scale), with the +-3 %
// target band shaded. A SPLIT note appears when the banks differ by more than 0.04. On overrun
// (throttle shut above 1500 rpm, where the injectors cut and the widebands read air) it says CUT
// instead of showing a scary lean number. Numbers are in the chosen mixture unit (units.js).
import { CHANNELS, shown, reading } from 'tl-mod:12';
import { steadyText } from 'tl-mod:17';

const RANGE = 0.15, BAND = 0.03, SPLIT = 0.04;
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

// Fuel cut on overrun: throttle closed with the revs up. (A Link fuel-cut channel would be better
// when the live block carries one.)
export const overrun = (r) => (r?.tps_pct ?? 100) < 2 && (r?.rpm ?? 0) > 1500;

// 'ok' | 'rich' | 'lean' | 'danger' | 'cut' | '' for one bank: e is the error (0.05 = 5 % lean).
export function bankState(e, cut) {
  if (cut) return 'cut';
  if (e === null) return '';
  return e > 0.08 ? 'danger' : e > BAND ? 'lean' : e < -BAND ? 'rich' : 'ok';
}

// Where a bank's bar sits, in % of the track width: { left, width, tick }.
export function barGeom(e) {
  const x = Math.max(-RANGE, Math.min(RANGE, e)) / RANGE * 50;
  return { left: 50 + Math.min(0, x), width: Math.abs(x), tick: 50 + x };
}

export function makeTwin() {
  const banks = [['lambda1', 'Bank 1'], ['lambda2', 'Bank 2']].map(([key, name]) => {
    const ch = shown(CHANNELS[key]);
    return { key, name: ch.note ? `${name} \u00b7 ${ch.note}` : name, ch, text: steadyText(ch) };   // its note (the dash's ranges): which cylinders it reads
  });
  const tgt = shown(CHANNELS.lambda_target);
  const el = document.createElement('div');
  el.className = 'box twin';
  el.innerHTML = `<div class="tw-head"><span>${esc(banks[0].ch.label.replace(/ 1$/, ''))}</span><span class="tw-split" hidden></span><span class="tw-tgt"></span></div>
    ${banks.map((b) => `<div class="tw-row"><div class="tw-k">${esc(b.name)}</div><div class="tw-n">-</div>
      <div class="tw-bar"><i class="tw-band"></i><i class="tw-fill"></i><i class="tw-tick"></i><span class="tw-cut">Fuel cut</span></div></div>`).join('')}
    <div class="tw-scale"><span class="rich">Rich</span><span>&minus;5%</span><span>+5%</span><span class="lean">Lean</span></div>`;
  const rows = [...el.querySelectorAll('.tw-row')].map((row) => ({ row, n: row.querySelector('.tw-n'), fill: row.querySelector('.tw-fill'), tick: row.querySelector('.tw-tick') }));
  const tgtEl = el.querySelector('.tw-tgt'), splitEl = el.querySelector('.tw-split');
  el.style.setProperty('--tw-band-l', `${50 - BAND / RANGE * 50}%`);
  el.style.setProperty('--tw-band-w', `${BAND / RANGE * 100}%`);
  return {
    el,
    // r: the whole reading (base units), since the box needs both banks, the target and the throttle.
    set(r) {
      const t = reading(CHANNELS.lambda_target, r?.lambda_target);
      const target = t ?? 1;
      tgtEl.textContent = t === null ? 'Target -' : `Target ${tgt.text(t)}`;
      const cut = overrun(r);
      const vals = banks.map((b) => reading(CHANNELS[b.key], r?.[b.key]));
      banks.forEach((b, i) => {
        const v = vals[i], e = v === null ? null : v / target - 1, st = bankState(e, cut), g = rows[i];
        g.row.dataset.st = st;
        g.n.textContent = cut ? 'CUT' : b.text(v);
        if (e === null || cut) { g.fill.style.width = '0'; g.tick.hidden = true; return; }
        const { left, width, tick } = barGeom(e);
        g.fill.style.left = `${left}%`; g.fill.style.width = `${width}%`;
        g.tick.hidden = false; g.tick.style.left = `${tick}%`;
      });
      const split = !cut && vals[0] !== null && vals[1] !== null && Math.abs(vals[0] - vals[1]) > SPLIT + 1e-9;
      splitEl.hidden = !split;
      if (split) splitEl.textContent = `Split ${Math.abs(vals[0] - vals[1]).toFixed(2)}`;
    },
    frame() {},
  };
}

// A short history of the live reading on the phone, for the Car tab's detail views (the 10 s and
// 30 s charts, the compass cloud, the G trail, the temperature trends). Fast channels are sampled
// 25 times a second for 30 s; slow ones once a second for 15 minutes. A missing value is NaN. Peak g for this drive is kept too.
import { overrun } from 'tl-mod:18';

export class Ring {
  constructor(n) { this.n = n; this.a = new Float32Array(n).fill(NaN); this.i = 0; this.len = 0; }
  push(v) { this.a[this.i] = typeof v === 'number' && Number.isFinite(v) ? v : NaN; this.i = (this.i + 1) % this.n; if (this.len < this.n) this.len++; }
  at(k) { return this.a[(this.i - 1 - k + this.n * 2) % this.n]; }   // k = 0 is the newest
  avg(n) { let s = 0, c = 0; for (let k = 0; k < Math.min(n, this.len); k++) { const v = this.at(k); if (!Number.isNaN(v)) { s += v; c++; } } return c ? s / c : null; }
}

export const FAST_HZ = 25;
const FAST_KEYS = ['rpm', 'tps_pct', 'map_kpa', 'lambda1', 'lambda2', 'lambda_target', 'oil_kpa', 'speed_kmh', 'g_lat', 'g_long'];
const SLOW_KEYS = ['ect_c', 'oil_temp_c', 'iat_c', 'battery_v'];

// Time with no readings is not stored: the rings simply stop, so the charts stop scrolling. Each stop
// longer than this is remembered as a break to mark on the chart.
const BREAK_MS = 3000;

export function createHistory() {
  const fast = Object.fromEntries(FAST_KEYS.map((k) => [k, new Ring(30 * FAST_HZ)]));
  const slow = Object.fromEntries(SLOW_KEYS.map((k) => [k, new Ring(900)]));
  const cut = new Ring(30 * FAST_HZ);
  const peak = { l: 0, r: 0, a: 0, b: 0 };
  const marks = { fast: { n: 0, last: -Infinity, list: [], size: 30 * FAST_HZ }, slow: { n: 0, last: -Infinity, list: [], size: 900 } };
  let clock = -Infinity;
  const stepped = (m, now) => {
    if (Number.isFinite(m.last) && now - m.last > BREAK_MS) m.list.push({ at: m.n, ms: now - m.last });
    m.last = now; m.n++;
    while (m.list.length && m.n - m.list[0].at > m.size) m.list.shift();
  };
  const rings = () => [...Object.entries(fast).map(([k, r]) => [`f:${k}`, r]), ...Object.entries(slow).map(([k, r]) => [`s:${k}`, r]), ['cut', cut]];
  return {
    fast, slow, cut, peak,
    // A copy of everything, for a dash starting up in its frame (it restores it there).
    snapshot() {
      return { rings: Object.fromEntries(rings().map(([k, r]) => [k, { a: r.a.slice(), i: r.i, len: r.len }])), peak: { ...peak }, marks: JSON.parse(JSON.stringify(marks)), clock };
    },
    restore(s) {
      for (const [k, r] of rings()) { const x = s?.rings?.[k]; if (x && x.a?.length === r.n) { r.a.set(x.a); r.i = x.i; r.len = x.len; } }
      Object.assign(peak, s?.peak || {});
      for (const kind of ['fast', 'slow']) {
        const m = s?.marks?.[kind];
        if (m) Object.assign(marks[kind], { n: m.n, last: m.last ?? -Infinity, list: m.list || [] });
      }
      clock = s?.clock ?? clock;
    },
    tick(now) { clock = now; },   // the time now, when no reading came with it
    // The breaks in the newest span samples of 'fast' or 'slow', newest first: [{k, ms}], the break lying
    // just older than sample k. k -1: no reading is coming in right now.
    breaks(kind, span) {
      const m = marks[kind], out = [];
      if (Number.isFinite(m.last) && clock - m.last > BREAK_MS) out.push({ k: -1, ms: clock - m.last });
      for (let i = m.list.length - 1; i >= 0; i--) {
        const k = m.n - 1 - m.list[i].at;
        if (k + 1 < span) out.push({ k, ms: m.list[i].ms });
      }
      return out;
    },
    // r: the reading (base units, phone values included); now: ms.
    push(r, now) {
      clock = now;
      if (now - marks.fast.last >= 1000 / FAST_HZ) {
        stepped(marks.fast, now);
        for (const k of FAST_KEYS) fast[k].push(r?.[k]);
        cut.push(overrun(r) ? 1 : 0);
        const x = r?.g_lat, y = r?.g_long;
        if (typeof x === 'number' && typeof y === 'number') {
          peak.r = Math.max(peak.r, x); peak.l = Math.max(peak.l, -x); peak.a = Math.max(peak.a, y); peak.b = Math.max(peak.b, -y);
        }
      }
      if (now - marks.slow.last >= 1000) { stepped(marks.slow, now); for (const k of SLOW_KEYS) slow[k].push(r?.[k]); }
    },
  };
}

export const hist = createHistory();

// The simulated drive (sim.js) fed to the Car tab as the app feeds it from the car: 10 readings a
// second kept as the app keeps the fast stream (the last minute of rows with their times, a new array
// each time; the dash caches row times per array), the newest reading, and two hours of temperature
// trend with the engine off for 40 minutes in the middle. Used by the dash development page
// (lab/dash-dev.js) and the app's test mode (test_mode.js). The charts start with the last 15 minutes already drawn; cold: a cold start
// with only its first 3 minutes drawn, the oil still warming; cooling: the oil falling all the way; fresh: nothing drawn, the charts start
// from 0 s as when the app has just opened.
// Returns getData() for initDash.
import { createSim, simTrends } from 'tl-mod:16';
import { setTrendSource } from 'tl-mod:13';
import { hist } from 'tl-mod:19';

export function simFeed({ cold = false, cooling = false, fresh = false } = {}) {
  const step = createSim({ cold, cooling });
  let fast = [], reading = null, last = Date.now();
  function tick() {
    const now = Date.now(), n = Math.max(1, Math.round((now - last) / 100));
    for (let k = 0; k < n; k++) reading = step(0.1);
    last = now;
    fast = [...fast.filter((r) => now - r.t < 60000), { t: now, ...reading }];
  }
  const LAP = 480, PAST = fresh ? 0 : (cold ? 4 : 19) * LAP, t0 = Date.now() - PAST * 100;   // whole laps of 48 s, so it starts at idle
  for (let k = 0; k < PAST; k++) { reading = step(0.1); hist.push(reading, t0 + k * 100); }
  tick(); setInterval(tick, 100);
  setTrendSource({ call: simTrends, bridge: () => 'sim' });
  const trend = Array.from({ length: 720 }, (_, i) => ({ t: Date.now() - (719 - i) * 10_000, ect_c: 140 + 15 * Math.sin(i / 60), iat_c: 30 + 3 * Math.sin(i / 90), oil_temp_c: 95 + 6 * Math.sin(i / 70) }))
    .filter((_, i) => i < 280 || i > 520);
  return () => ({ fast, fastRunning: true, reading, trend });
}

// Acceleration timers from GPS speed (km/h): 0-60 mph (or 0-100 km/h) from a stop, and the rolling
// passing measure 50-70 mph (80-120 km/h). Pure: runStep() takes the last state, the reading and
// the time, and gives the new state with what's timing now (live) and the last finished run (last).
// A run is dropped if the car slows or it takes over 25 s. The leanest mixture during the run
// (averaged a little, and not at fuel cut) comes with the result.
const MPH = 1.609344;
export const RUNS = {
  mph: { stop: { name: '0-60 mph', lo: 0, hi: 60 * MPH }, pass: { name: '50-70 mph', lo: 50 * MPH, hi: 70 * MPH } },
  kmh: { stop: { name: '0-100 km/h', lo: 0, hi: 100 }, pass: { name: '80-120 km/h', lo: 80, hi: 120 } },
};

const lean = (r) => {
  const t = r?.lambda_target ?? 1, ls = [r?.lambda1, r?.lambda2].filter((x) => typeof x === 'number' && x < 1.26);
  return ls.length ? Math.max(...ls) / t - 1 : null;
};

// st: { prev, prevAt, armed, live, last } ({} to start); r: reading with speed_kmh; system 'mph'|'kmh'.
export function runStep(st, r, now, system = 'mph') {
  const s = { armed: false, live: null, last: null, ...st };   // armed once the car has been seen stopped
  const v = r?.speed_kmh, def = RUNS[system] || RUNS.mph;
  if (typeof v !== 'number') return { ...s, prev: null };
  const prev = s.prev;
  s.prev = v; s.prevAt = now;
  if (v < 1) { s.armed = true; s.live = null; return s; }
  let live = s.live;
  // start: rolling away from a stop, or crossing the pass's low speed while speeding up
  if (!live && s.armed && v >= 1) { live = { kind: 'stop', t0: now, leanest: null }; s.armed = false; }
  else if (!live && prev !== null && prev < def.pass.lo && v >= def.pass.lo) live = { kind: 'pass', t0: now, leanest: null };
  if (live) {
    const d = def[live.kind];
    if (prev !== null && v < prev - 3) live = null;                    // slowing: not a run
    else if (now - live.t0 > 25000) live = null;
    else {
      const e = (r.tps_pct ?? 100) > 2 ? lean(r) : null;
      if (e !== null) live = { ...live, leanest: live.leanest === null ? e : Math.max(live.leanest, e) };
      if (v >= d.hi) {
        const f = prev !== null && v > prev ? (d.hi - prev) / (v - prev) : 1;
        const time = (now - live.t0 - (1 - f) * (now - (st.prevAt ?? now))) / 1000;
        s.last = { name: d.name, time, leanest: live.leanest, at: now };
        live = null;
      }
    }
  }
  s.live = live ? { ...live, name: def[live.kind].name, t: (now - live.t0) / 1000 } : null;
  return s;
}

// Each row's time (its t) in ms, worked out once per rows array.
const times = new WeakMap();
export function rowTimes(rows) {
  let t = times.get(rows);
  if (!t) { t = rows.map((r) => new Date(r.t).getTime()); times.set(rows, t); }
  return t;
}

// "9:41 pm": clock times in 12-hour form, local time.
export function clock12(d) {
  const t = new Date(d);
  const h = t.getHours() % 12 || 12;
  return `${h}:${String(t.getMinutes()).padStart(2, '0')} ${t.getHours() < 12 ? 'am' : 'pm'}`;
}

// A promise that gives up after ms: it rejects with "<what> took over N s" when the answer hasn't come
// by then (a request that never answers would otherwise wait for ever).
export function within(promise, ms, what = 'request') {
  let timer;
  const late = new Promise((_, reject) => { timer = setTimeout(() => reject(new Error(`${what} took over ${Math.round(ms / 1000)} s`)), ms); });
  return Promise.race([promise, late]).finally(() => clearTimeout(timer));
}

// The dash preview: one dash in the same sandboxed frame the Car tab uses (js/dash/frame.js), at
// phone size, on the simulated drive (js/dash/sim_feed.js), with whether it started, the errors it
// threw, its paint lag and its frame rate beside it. It is the Dash Dev page (dash-dev.js) cut down to
// what a look at a dash needs, and made to run with no server: scripts/dash_tools.mjs packs this
// module, everything it imports, the page around it (preview_page.js) and the dash fonts into one file for the
// public dashes repo, whose tools/preview.mjs adds a dash's files and writes preview.html. A person's
// AI opens that file in its own browser and takes a picture of it, so it sees what the phone will
// show, and what went wrong, before it pushes.
// The page hands over `globalThis.TL_PREVIEW`: { files: the dash's {path: text}, app: { text: {path
// under src/: text}, bytes: {path: base64} } (the app files the frame reads: the dash fonts) }.
// Address parameters: ?sideways (a phone on its side), ?settings (the dash's own settings opened, as
// a tap on the app's gear does), and as the app's test mode takes them (js/dash/test_mode.js) ?cold,
// ?cooling, ?fresh; every other one goes to the dash as api.params. What happened is also on
// `globalThis.tlPreview` ({ status: 'loading' | 'running' | 'stopped', reason, errors, painted, fps,
// lag }) and in the page's title, for a script that would rather read than look.
import { createDashFrame } from 'tl-mod:9';
import { setAppFiles } from 'tl-mod:3';
import { trendRequest } from 'tl-mod:14';
import { parseTest } from 'tl-mod:15';
import { simFeed } from 'tl-mod:20';
import { runStep } from 'tl-mod:21';
import { UNITS, units, unitFor } from 'tl-mod:11';
import { hist } from 'tl-mod:19';
import { rowTimes } from 'tl-mod:22';

const given = globalThis.TL_PREVIEW;
if (given) {
  const $ = (id) => document.getElementById(id);
  const bytes = (b64) => Uint8Array.from(atob(b64), (c) => c.charCodeAt(0)).buffer;
  setAppFiles({ text: async (p) => given.app?.text?.[p] ?? null, bytes: async (p) => (given.app?.bytes?.[p] ? bytes(given.app.bytes[p]) : null) });

  const query = new URLSearchParams(location.search);
  const OWN = ['sideways', 'settings'];
  const test = parseTest(`?test&${new URLSearchParams([...query].filter(([k]) => !OWN.includes(k)))}`);
  const getData = simFeed(test);   // also the history requests' source (simTrends)
  const [w, h] = query.has('sideways') ? [844, 390] : [390, 844];
  Object.assign($('stage').style, { width: `${w}px`, height: `${h}px` });

  const report = globalThis.tlPreview = { status: 'loading', reason: '', errors: [], painted: false, fps: null, lag: null };
  const say = (status, reason = '') => {
    Object.assign(report, { status, reason });
    $('status').textContent = status === 'running' ? 'Running' : status === 'stopped' ? `Stopped: ${reason}` : 'Loading';
    $('status').classList.toggle('bad', status === 'stopped');
    document.title = `Dash preview: ${status}${reason ? `: ${reason}` : ''}`;
  };
  const error = (text) => { report.errors.push(text); $('errors').textContent = report.errors.join('\n'); };

  let id = 'dash', memory, choices = units(), runSt = {};
  try { id = JSON.parse(given.files['dash.json']).id || id; } catch { /* the loader says why */ }
  const startedAt = performance.now();
  say('loading');
  const frame = createDashFrame({ hash: 'preview', id, files: given.files }, {
    units: choices, bridge: 'sim', tune: { rev_limit: 7500 },
    params: Object.keys(test.params).length ? test.params : null, history: () => hist.snapshot(), request: trendRequest,
    store: { load: () => memory, save(obj) { memory = obj; } },   // for this page only
    onReady: (f) => {
      say('running');
      if (query.has('settings')) f.openSettings();
      const m = f.manifest;
      $('info').textContent = `${m.name} ${m.version} · dash API ${m.api}${m.feeds.length ? ` · feeds ${m.feeds.join(', ')}` : ''}`;
    },
    onFirstPaint: () => { report.painted = true; $('paint').textContent = `${Math.round(performance.now() - startedAt)} ms after it was started`; },
    // The tab bar as the app answers a dash: shown or hidden as asked.
    onNav: (show) => frame.nav(show),
    onUnit: (kind, key) => {
      if (typeof kind !== 'string' || typeof key !== 'string' || !Object.hasOwn(UNITS, kind) || !Object.hasOwn(UNITS[kind].options, key)) return;
      choices = { ...choices, [kind]: key };
      frame.units(choices);
    },
    onError: error,
    onBeat: ({ lag, lagMax, fps }) => {
      if (lag !== null) { report.lag = lag; $('lag').textContent = `${lag} ms average, ${lagMax} ms worst (last second)`; }
      if (fps !== null) { report.fps = fps; $('fps').textContent = `${fps} frames a second`; }
    },
    onFail: (reason) => say('stopped', reason),
  });
  $('stage').append(frame.el);

  // Each frame: the newest simulated reading to the dash with the acceleration timers, the live
  // chart's rows and the trend, as the Car tab does on Direct (js/dash/car_tab.js feed).
  requestAnimationFrame(function tick() {
    requestAnimationFrame(tick);
    const { fast, reading, trend } = getData(), t = Date.now();
    const value = { ...reading, tilt_x: null, tilt_y: null };
    runSt = runStep(runSt, value, t, unitFor('speed', choices).key === 'mph' ? 'mph' : 'kmh');
    value.run = runSt;
    hist.tick(t);
    hist.push(value, t);   // the snapshot a dash starts from
    if (frame.failed) return;
    frame.reading(value, t, { dim: false, smoothMs: 70, digitsHz: null });
    const tms = rowTimes(fast);
    frame.rows(fast, tms, tms[tms.length - 1]);
    frame.trend(trend);
  });
  document.addEventListener('pointerdown', (e) => { if (e.target !== frame.el) frame.outside(); }, true);
}

text.kit/themes.css:
/* The kit's themes: the dash fonts, each gauge style's colours and type (--d-* on .dash[data-theme]),
   and the alarm banner's look. The boxes, numbers and charts draw only with these variables, so a new
   theme is one block here plus a line in the dash's THEMES (dashes/tunerloop-dash/box_list.js). The app
   loads this file too (the action buttons' banner, js/feedback.js); a dash's frame gets it without the
   @font-face rules (the fonts go to a frame as bytes: js/dash/loader.js). */
/* Oxanium (SIL Open Font License, fonts/oxanium-OFL.txt), from @fontsource/oxanium 5.3.0: the Vintage styles' type.
   Boxy and racy, and its 1 has a flag and a foot, so digits held in equal-width slots (nothing bounces) don't leave gaps. */
@font-face { font-family: Oxanium; font-weight: 600; font-display: swap; src: url("../fonts/oxanium-latin-600-normal.woff2") format("woff2"); }
@font-face { font-family: Oxanium; font-weight: 700; font-display: swap; src: url("../fonts/oxanium-latin-700-normal.woff2") format("woff2"); }
/* Saira (SIL Open Font License, fonts/saira-OFL.txt), from @fontsource/saira 5.2.10: the Vintage
   theme's numerals, the closest open match to classic VDO gauge type. */
@font-face { font-family: Saira; font-weight: 600; font-display: swap; src: url("../fonts/saira-latin-600-normal.woff2") format("woff2"); }
@font-face { font-family: Saira; font-weight: 700; font-display: swap; src: url("../fonts/saira-latin-700-normal.woff2") format("woff2"); }
/* Saira variable (weight and width axes; same OFL), from @fontsource-variable/saira 5.3.0: the dial
   numerals at full width, wide and heavy like the VDO faces' print. */
@font-face { font-family: "Saira VF"; font-weight: 100 900; font-stretch: 50% 125%; font-display: swap; src: url("../fonts/saira-latin-variable-normal.woff2") format("woff2"); }
/* Barlow Condensed (SIL Open Font License, fonts/barlow-condensed-OFL.txt), from @fontsource/barlow-condensed 5.2.6:
   the Race theme's type (Vintage falls back to it), bundled so every phone draws the same. */
@font-face { font-family: "Barlow Condensed"; font-weight: 500; font-display: swap; src: url("../fonts/barlow-condensed-latin-500-normal.woff2") format("woff2"); }
@font-face { font-family: "Barlow Condensed"; font-weight: 700; font-display: swap; src: url("../fonts/barlow-condensed-latin-700-normal.woff2") format("woff2"); }

/* What the boxes assume of the page around them, the same in the app and in a dash's frame. */
.dash { font: 19.8px/1.4 system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen', 'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue', 'Segoe UI Emoji', 'Apple Color Emoji', 'Noto Color Emoji', sans-serif; word-wrap: break-word; }

/* ---------------------------------------------------------------- themes */
.dash {
  --d-face: #141416; --d-ring: #2c2c31; --d-tick: #c9c9cf; --d-num: #e6e6ea; --d-label: #8d8d96;
  --d-needle: #ff6a2a; --d-hub: #26262a; --d-value: #ffffff; --d-warn: #f0b429; --d-red: #e5484d; --d-cold: #4aa8ff;
  --d-grid: rgba(255, 255, 255, 0.08); --d-ok: #5fe3a1; --d-b2: #c6a3ff; --d-rich: #4aa8ff; --d-lean: #ff8a3d; --d-track: rgba(255, 255, 255, 0.07);
  --d-s-rpm: #ff6a2a; --d-s-tps: #4fa3e0; --d-s-map: #8fd18f; --d-s-ect: #ff6a2a; --d-s-iat: #4fa3e0; --d-s-oil: #c9a227;
  --d-font: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; --d-num-weight: 600; --d-value-style: normal;
}
/* Vintage: classic VDO instruments (964-era): charcoal faces, white numerals in a wide rounded
   type, white ticks, a long Porsche-orange needle on a plain black hub, the redline as orange
   marks, and speed in orange on a dark LCD. */
.dash:is([data-theme="vintage"], [data-theme="vintage3d"]) {
  --d-face: #171717; --d-ring: #050505; --d-tick: #f2f2f0; --d-num: #f2f2f0; --d-label: #cfcfcc;
  --d-needle: #ff6a1a; --d-hub: #0c0c0c; --d-value: #f2f2f0; --d-warn: #ff8c2e; --d-red: #e8402a;
  --d-grid: rgba(242, 242, 240, 0.1); --d-ok: #8fd18f; --d-b2: #7fb3d9; --d-rich: #7fb3d9; --d-lean: #ff8c2e; --d-track: rgba(242, 242, 240, 0.08);
  --d-s-rpm: #ff6a1a; --d-s-tps: #f2f2f0; --d-s-map: #ff8c2e; --d-s-ect: #ff6a1a; --d-s-iat: #f2f2f0; --d-s-oil: #ff8c2e;
  --d-lcd: #ff6a1f; --d-lcd-bg: #2b140b; --d-cold: #e8c33a;   /* warm-up ticks: VDO yellow */
  --d-font: Oxanium, Saira, "Barlow Condensed", "Arial Narrow", sans-serif;
  --d-num-weight: 700;
}
.dash:is([data-theme="vintage"], [data-theme="vintage3d"]) .gauge .ring { stroke-width: 7; }
.dash:is([data-theme="vintage"], [data-theme="vintage3d"]) .gauge .tk { stroke-width: 3.4; }
.dash:is([data-theme="vintage"], [data-theme="vintage3d"]) .gauge .num { font-family: "Saira VF", Oxanium, sans-serif; font-weight: 700; font-stretch: 125%; font-variation-settings: "wdth" 125; }
/* the traced VDO digits (js/vdo-digits.js) where a dial has them, the font elsewhere */
.gauge .numg { display: none; fill: var(--d-num); fill-rule: evenodd; }
.dash:is([data-theme="vintage"], [data-theme="vintage3d"]) .gauge .has-vdo .numg { display: inline; }
.dash:is([data-theme="vintage"], [data-theme="vintage3d"]) .gauge .has-vdo .num { display: none; }
.dash:is([data-theme="vintage"], [data-theme="vintage3d"]) .gauge .tm { stroke-width: 1.5; opacity: 0.9; stroke-dasharray: 9.5 99; }
/* Vintage, like the VDO faces: long and short ticks closer in length than the other styles (13 and 9.5), and the
   redline as orange ticks, no arc */
.dash:is([data-theme="vintage"], [data-theme="vintage3d"]) .gauge .tk { stroke-dasharray: 13 99; }
.dash:is([data-theme="vintage"], [data-theme="vintage3d"]) .gauge .zone { display: none; }
.dash:is([data-theme="vintage"], [data-theme="vintage3d"]) .gauge .hot { stroke: var(--d-needle); }
.dash:is([data-theme="vintage"], [data-theme="vintage3d"]) .gauge .cold { stroke: var(--d-cold); }   /* still warming up: yellow ticks */
.dash:is([data-theme="vintage"], [data-theme="vintage3d"]) .gauge .zone { stroke-width: 4; }
.dash:is([data-theme="vintage"], [data-theme="vintage3d"]) .gauge .zone.red, .dash:is([data-theme="vintage"], [data-theme="vintage3d"]) .gauge .zone.warn { stroke: var(--d-needle); }
.dash:is([data-theme="vintage"], [data-theme="vintage3d"]) .gauge .hub { stroke: none; r: 13px; }
.dash:is([data-theme="vintage"], [data-theme="vintage3d"]) .gauge .lbl { letter-spacing: 0.04em; text-transform: none; font-weight: 600; }
.gauge .lbl, .gauge .note { transform: translateY(56px); }
/* Vintage: the name and the note under it ("RPM" over "x1000") small and the same size, one line apart */
.dash:is([data-theme="vintage"], [data-theme="vintage3d"]) .gauge .lbl { font-size: 7.5px; transform: translateY(59.5px); }
.dash:is([data-theme="vintage"], [data-theme="vintage3d"]) .gauge .note { font-size: 7.5px; }   /* under the hub, clear of the needle */   /* under the hub, like "1/min x1000" on the VDO tach */
/* Race: a white-faced racing tach: black numerals, red needle, heavy type. */
.dash[data-theme="race"] {
  --d-face: #f3f1ea; --d-ring: #111111; --d-tick: #111111; --d-num: #111111; --d-label: #5b5b5b;
  --d-needle: #d7261e; --d-hub: #111111; --d-value: #111111; --d-warn: #c98a00; --d-red: #d7261e;
  --d-grid: rgba(0, 0, 0, 0.1); --d-ok: #2e7a47; --d-b2: #6a3fb0; --d-rich: #1f5fae; --d-lean: #c25a00; --d-track: rgba(0, 0, 0, 0.08);
  --d-s-rpm: #d7261e; --d-s-tps: #1f5fae; --d-s-map: #2e7a47; --d-s-ect: #d7261e; --d-s-iat: #1f5fae; --d-s-oil: #8a6d00;
  --d-font: "Barlow Condensed", "Arial Narrow", sans-serif; --d-num-weight: 700; --d-value-style: italic;
}

/* Vintage 3D: the same look with subtle depth and light from the upper left. Dials get a recessed face,
   a lit bezel, a beveled needle casting a soft shadow, a domed cap and faint glass (shared SVG
   gradients and filters, #d3-*, kit/d3defs.js, put in once by the dash); panels are recessed, bars sit in inset
   tracks with a slight highlight, numbers have a faint printed shadow and the LCD digits glow. */
.dash[data-theme="vintage3d"] { --d-needle-lit: #ff9a55; --d-needle-dark: #b8440c; --d-num: #e4e2dc; --d-tick: #e4e2dc; --d-label: #c4c2bc; }   /* print white, warm and a touch grey like the real faces */
.dash[data-theme="vintage3d"] .panel { background: radial-gradient(120% 95% at 28% 18%, #1f1f1f, #141414 60%, #0c0c0c);
  box-shadow: inset 0 3px 10px rgba(0, 0, 0, 0.8), inset 0 -1px 0 rgba(255, 255, 255, 0.05); }
.dash[data-theme="vintage3d"] .gauge .face { fill: url(#d3-face); }
.dash[data-theme="vintage3d"] .gauge .ring { stroke: url(#d3-bezel); stroke-width: 8; }
.dash[data-theme="vintage3d"] .gauge .lip { display: inline; }
.dash[data-theme="vintage3d"] .gauge .glass, .dash[data-theme="vintage3d"] .gauge .rim { display: inline; }
.dash[data-theme="vintage3d"] .gauge .nwrap { filter: url(#d3-shadow); }
.dash[data-theme="vintage3d"] .gauge .needle .nl { fill: var(--d-needle-lit); }
.dash[data-theme="vintage3d"] .gauge .needle .nr { fill: var(--d-needle-dark); }
.dash[data-theme="vintage3d"] .gauge .needle.flip .nl { fill: var(--d-needle-dark); }
.dash[data-theme="vintage3d"] .gauge .needle.flip .nr { fill: var(--d-needle-lit); }
.dash[data-theme="vintage3d"] .gauge .hub { fill: url(#d3-cap); }
.dash[data-theme="vintage3d"] .gauge .print { filter: url(#d3-print); }
.dash[data-theme="vintage3d"] .big-v, .dash[data-theme="vintage3d"] .tw-n, .dash[data-theme="vintage3d"] .pull .pl-rpm .v, .dash[data-theme="vintage3d"] .grid .n {
  text-shadow: 0 2px 2px rgba(0, 0, 0, 0.85), 0 -1px 0 rgba(255, 255, 255, 0.07); }
.dash[data-theme="vintage3d"] .speed .sp-lcd { text-shadow: 0 0 0.35em rgba(255, 106, 31, 0.45);
  box-shadow: inset 0 0 0 0.6cqmin #0b0503, inset 0 2cqmin 3cqmin rgba(0, 0, 0, 0.6); }
.dash[data-theme="vintage3d"] .tw-bar, .dash[data-theme="vintage3d"] .speed .sp-bar { box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.8), 0 1px 0 rgba(255, 255, 255, 0.06); }
.dash[data-theme="vintage3d"] .tw-fill, .dash[data-theme="vintage3d"] .speed .sp-bar i { box-shadow: inset 0 2px 0 rgba(255, 255, 255, 0.28), inset 0 -3px 4px rgba(0, 0, 0, 0.35), 0 0 8px color-mix(in srgb, currentColor 0%, transparent); }
.dash[data-theme="vintage3d"] .tw-tick, .dash[data-theme="vintage3d"] .tw-bar::after { box-shadow: 1px 2px 3px rgba(0, 0, 0, 0.7); }
.dash[data-theme="vintage3d"] .chart-plot { border-radius: 8px; box-shadow: inset 0 3px 8px rgba(0, 0, 0, 0.75); background: rgba(0, 0, 0, 0.18); }
.dash[data-theme="vintage3d"] .chart-plot::after { content: ""; position: absolute; inset: 0; border-radius: 8px; pointer-events: none;
  background: linear-gradient(160deg, rgba(255, 255, 255, 0.07), rgba(255, 255, 255, 0) 40%); }
.dash[data-theme="vintage3d"] .grid .cell { box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.03); }
.dash[data-theme="vintage3d"] .alarm { box-shadow: inset 0 2px 0 rgba(255, 255, 255, 0.25), inset 0 -4px 8px rgba(0, 0, 0, 0.3), 0 -6px 24px rgba(0, 0, 0, 0.5); }
.dash[data-theme="vintage3d"] .gauge .bare { display: none; }   /* the real tach prints no 0 or 8 */
.gauge .lip, .gauge .glass, .gauge .rim { display: none; }
.gauge .lip { fill: none; stroke: #000; stroke-width: 12; transform: translate(var(--d3-lx, -3px), var(--d3-ly, -4px)); }
.gauge .glass { fill: url(#d3-glass); pointer-events: none; }
.gauge .rim { fill: none; stroke: rgba(255, 255, 255, 0.16); stroke-width: 2.6; filter: url(#d3-glare); transform: rotate(var(--d3-turn, 0deg)); }   /* the glass's reflected arc: soft, not a drawn line */
.d3-defs { position: absolute; width: 0; height: 0; overflow: hidden; }

/* ---------------------------------------------------------------- the alarm banner (alarm_banner.js) */
.alarm { margin: 0; border: 0; border-radius: 14px; padding: 0.35em 0.6em; cursor: pointer;
  font: 700 clamp(20px, 5.5vmin, 42px) / 1.1 var(--d-font, system-ui, sans-serif); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; letter-spacing: 0.02em; text-transform: uppercase; text-align: center; color: #fff; background: var(--d-red, #e5484d); box-shadow: 0 -6px 24px rgba(0, 0, 0, 0.5); }
.alarm[data-sev="warn"] { font-size: clamp(16px, 4.2vmin, 30px); color: #111; background: var(--d-warn, #f0b429); }
.alarm[data-sev="ok"] { font-size: clamp(16px, 4.2vmin, 30px); color: #c9f2d5; background: #1f5130; }   /* the status checklist's green */
